async function benchWorkerWorkloads(capabilities, options = {}) {
  if (!capabilities.cpu.workerAvailable || capabilities.cpu.suggestedWorkers < 2) return null;
  const workerCount = clamp(finite(options.workerCount, capabilities.cpu.suggestedWorkers) | 0, 2, capabilities.cpu.suggestedWorkers);
  const samplesN = Math.max(2, finite(options.samples, 3) | 0);
  const pool = new ManagedWorkerPool({ size: workerCount, source: BENCH_WORKER_SOURCE, name: 'diagram-compute-bench' });
  await pool.init();
  try {
    const out = { workers: workerCount, workloads: {}, latencyMs: null };
    // Persistent-pool dispatch latency, deliberately tiny job.
    const ping = [];
    for (let s = 0; s < Math.max(4, samplesN); s++) { const t = now(); await pool.run({ kind: 'ping', items: 1 }); ping.push(now() - t); }
    out.latencyMs = median(ping);

    async function runPartitioned(kind, totalItems, repeats = 1) {
      let sink = 0;
      const times = await timedSamples(samplesN, async () => {
        const res = await pool.runPartitions(totalItems, ({ index, start, count }) => ({ kind, items: count, repeats, offset: start + index }));
        sink += res.reduce((a, v) => a + finite(v, 0), 0);
      });
      /* Every partitioned sample contains one pool dispatch round trip, and estimateDefaultMs adds
         that same round trip again as backendLatency(profile,'workers'). It is removed here so it is
         charged exactly once; the floor keeps a dispatch-dominated sample from reaching zero. */
      const dispatchMs = Math.max(0, finite(out.latencyMs, 0));
      const net = times.map(t => Math.max(t - dispatchMs, t * 0.05));
      return benchResult(net, totalItems, repeats, { sink, dispatchMs, grossMs: Math.min(...times) });
    }
    out.workloads.branchy = await runPartitioned('branchy', finite(options.branchyItems, 300_000) | 0, 1);
    out.workloads['monte-carlo'] = { ...out.workloads.branchy };
    out.workloads.vector = await runPartitioned('vector', finite(options.vectorItems, 2 << 20) | 0, finite(options.vectorRepeats, 6) | 0);
    out.workloads.stencil = await runPartitioned('stencil', finite(options.stencilItems, 1024 * 1024) | 0, finite(options.stencilRepeats, 5) | 0);
    out.workloads['stencil-3d'] = await runPartitioned('stencil-3d', finite(options.stencil3DItems, 512 * 1024) | 0, finite(options.stencil3DRepeats, 3) | 0);
    out.workloads.sparse = await runPartitioned('sparse', finite(options.sparseItems, 512 * 1024) | 0, finite(options.sparseRepeats, 4) | 0);
    out.workloads.reduction = await runPartitioned('reduction', finite(options.reductionItems, 2 << 20) | 0, finite(options.reductionRepeats, 8) | 0);
    out.workloads.particles = await runPartitioned('particles', finite(options.particleItems, 2 << 19) | 0, finite(options.particleRepeats, 12) | 0);
    out.workloads.rays = await runPartitioned('rays', finite(options.rayItems, 360_000) | 0, finite(options.rayRepeats, 4) | 0);
    out.workloads.generic = { ...out.workloads.vector };
    return out;
  } finally { pool.destroy(); }
}

