    const shape=raw.map(v=>Math.floor(finite(v,0)));
    if(!shape.length||shape.some(v=>!(v>0)))throw err(`Array tally '${this.name}' requires a positive shape, got [${raw.join(', ')}]`,'BAD_ARRAY_TALLY');
    this.shape=shape;this.size=shape.reduce((a,b)=>a*b,1);
    const dtype=String(spec.dtype||'f64').toLowerCase();
    if(dtype!=='f64')throw err(`Array tally '${this.name}' accumulator dtype must be 'f64' (asked for '${dtype}'): a mesh accumulated in f32 loses the sum of squares long before the run ends`,'BAD_ARRAY_TALLY');
    this.dtype=dtype;
    const estimator=String(spec.estimator||'').toLowerCase();
    if(!ARRAY_TALLY_ESTIMATORS.includes(estimator))
      throw err(`Array tally '${this.name}' needs an explicit estimator (${ARRAY_TALLY_ESTIMATORS.join(' | ')}): the two answer different questions and disagree exactly when histories are correlated, so there is no safe default`,'BAD_ARRAY_TALLY');
    this.estimator=estimator;
