    this.batchSize=Math.max(0,Math.floor(finite(spec.batchSize,0)));
    if(estimator==='batch-means'&&this.batchSize<=0)throw err(`Array tally '${this.name}' with estimator 'batch-means' requires batchSize > 0`,'BAD_ARRAY_TALLY');
    const wire=String(spec.transferDtype||'f64').toLowerCase();
    if(wire!=='f64'&&wire!=='f32')throw err(`Array tally '${this.name}' transferDtype must be 'f64' or 'f32'`,'BAD_ARRAY_TALLY');
    this.transferDtype=wire;
    this.partition=Number.isFinite(Number(spec.partition))?Math.floor(Number(spec.partition)):null;
    this.sum=new Float64Array(this.size);this.sum2=new Float64Array(this.size);
    this.histories=0;this.weight=0;this.weight2=0;this.rejected=0;this.scores=0;
    this._cur=new Float64Array(this.size);this._stamp=new Int32Array(this.size).fill(-1);this._touched=[];
    this.batches=0;this.batchHistories=0;this.minBatch=0;this.maxBatch=0;this.equalBatches=true;
    this._pending=0;
    if(estimator==='batch-means'){this.batchSum=new Float64Array(this.size);this.batchSum2=new Float64Array(this.size);this._bcur=new Float64Array(this.size);}
    else {this.batchSum=null;this.batchSum2=null;this._bcur=null;}
