/* ------------------------- GPU lifecycle ---------------------------- */

class GPUResourceScope {
  constructor(device) { this.device = device; this.resources = new Set(); this.destroyed = false; }
  track(resource) { if (resource) this.resources.add(resource); return resource; }
  createBuffer(desc) { return this.track(this.device.createBuffer(desc)); }
  untrack(resource) { this.resources.delete(resource); return resource; }
  destroy() {
    if (this.destroyed) return; this.destroyed = true;
    for (const r of this.resources) { try { r.destroy?.(); } catch { /* ignore */ } }
    this.resources.clear();
  }
}

