    const input=(v,label)=>{if(isArrayBufferLike(v)&&!(v instanceof Float32Array))throw err(`GPU Jacobi ${label} TypedArray must be Float32Array`,'BAD_JACOBI_INPUT');return v;};
    if(!(z instanceof ComputeResource)&&!isGPUBufferLike(z))throw err('GPU Jacobi output z must be a GPUBuffer or ComputeResource','BAD_JACOBI_OUTPUT');
