      bindings.push({binding:4,value:await this._operand(x,device,{readWrite:entry==='relax',temps,scope:options.scope,label:'x'})});
      if(y!=null)bindings.push({binding:5,value:await this._operand(y,device,{output:true,temps,scope:options.scope,label:'y'}),output:true});
