  residual(x,b,r,options={}){return this._run('residual',{x,y:r,rhs:b,options});}
  /** One red-black Gauss-Seidel sweep over `colour` (0, 1, or 2 for every cell). In place on x. */
  relax(x,b,options={}){const colour=options.colour===undefined?2:Math.max(0,Math.floor(finite(options.colour,2)));if(colour>2)throw err('Stencil relax colour must be 0, 1 or 2 (2 = every cell)','BAD_STENCIL');return this._run('relax',{x,rhs:b,colour,options});}
