function u32ScanWGSL(wg){return `
struct Params{n:u32,offset:u32,groupsX:u32,_p0:u32};@group(0) @binding(0) var<storage,read> inputData:array<u32>;@group(0) @binding(1) var<storage,read_write> outputData:array<u32>;@group(0) @binding(2) var<uniform> params:Params;
@compute @workgroup_size(${wg}) fn main(@builtin(local_invocation_id) lid:vec3<u32>,@builtin(workgroup_id) wid:vec3<u32>){let groupIndex=wid.x+wid.y*params.groupsX;let i=groupIndex*${wg}u+lid.x;if(i>=params.n){return;}var v=inputData[i];if(i>=params.offset){v=v+inputData[i-params.offset];}outputData[i]=v;}`;}
function u32ShiftWGSL(wg){return `
struct Params{n:u32,groupsX:u32,_p0:u32,_p1:u32};@group(0) @binding(0) var<storage,read> inclusiveData:array<u32>;@group(0) @binding(1) var<storage,read_write> exclusiveData:array<u32>;@group(0) @binding(2) var<uniform> params:Params;
@compute @workgroup_size(${wg}) fn main(@builtin(local_invocation_id) lid:vec3<u32>,@builtin(workgroup_id) wid:vec3<u32>){let groupIndex=wid.x+wid.y*params.groupsX;let i=groupIndex*${wg}u+lid.x;if(i>=params.n){return;}exclusiveData[i]=select(inclusiveData[i-1u],0u,i==0u);}`;}
function u32CompactWGSL(wg){return `
struct Params{n:u32,groupsX:u32,capacity:u32,_p0:u32};@group(0) @binding(0) var<storage,read> flags:array<u32>;@group(0) @binding(1) var<storage,read> offsets:array<u32>;@group(0) @binding(2) var<storage,read_write> indices:array<u32>;@group(0) @binding(3) var<storage,read_write> countOut:array<u32>;@group(0) @binding(4) var<uniform> params:Params;
@compute @workgroup_size(${wg}) fn main(@builtin(local_invocation_id) lid:vec3<u32>,@builtin(workgroup_id) wid:vec3<u32>){let groupIndex=wid.x+wid.y*params.groupsX;let i=groupIndex*${wg}u+lid.x;if(i>=params.n){return;}let f=select(0u,1u,flags[i]!=0u);let pos=offsets[i];if(f!=0u&&pos<params.capacity){indices[pos]=i;}if(i==params.n-1u){let total=pos+f;countOut[0]=min(total,params.capacity);countOut[1]=select(0u,total-params.capacity,total>params.capacity);}}`;}
function u32HistogramWGSL(wg){return `
struct Params{n:u32,bins:u32,groupsX:u32,_p0:u32};@group(0) @binding(0) var<storage,read> values:array<u32>;@group(0) @binding(1) var<storage,read_write> counts:array<atomic<u32>>;@group(0) @binding(2) var<uniform> params:Params;
@compute @workgroup_size(${wg}) fn main(@builtin(local_invocation_id) lid:vec3<u32>,@builtin(workgroup_id) wid:vec3<u32>){let groupIndex=wid.x+wid.y*params.groupsX;let i=groupIndex*${wg}u+lid.x;if(i>=params.n){return;}let v=values[i];if(v<params.bins){atomicAdd(&counts[v],1u);}}`;}
async function readbackGPUU32(device,buffer,count,offsetElements=0){const n=Math.max(0,Math.floor(finite(count,0))),size=aligned4(n*4),srcOffset=Math.max(0,Math.floor(finite(offsetElements,0)))*4,staging=device.createBuffer({size,usage:GPU_USAGE.COPY_DST|GPU_USAGE.MAP_READ,label:'diagram-gpu-u32-readback'});try{const enc=device.createCommandEncoder();enc.copyBufferToBuffer(buffer,srcOffset,staging,0,size);device.queue.submit([enc.finish()]);await staging.mapAsync(GPU_MAP.READ,0,size);const out=new Uint32Array(n);out.set(new Uint32Array(staging.getMappedRange(0,size),0,n));staging.unmap();return out;}finally{try{staging.destroy();}catch{}}}
