export function gpuU32QueueWGSL({group=0,idsBinding=0,stateBinding=1,prefix='diagram_queue'}={}){const p=String(prefix).replace(/[^A-Za-z0-9_]/g,'_');return `
struct ${p}_State{count:atomic<u32>,overflow:atomic<u32>,capacity:u32,_pad:u32};
@group(${group}) @binding(${idsBinding}) var<storage,read_write> ${p}_ids:array<u32>;
@group(${group}) @binding(${stateBinding}) var<storage,read_write> ${p}_state:${p}_State;
fn ${p}_count()->u32{return min(atomicLoad(&${p}_state.count),${p}_state.capacity);}
fn ${p}_id(i:u32)->u32{return ${p}_ids[i];}
fn ${p}_push(id:u32)->bool{let slot=atomicAdd(&${p}_state.count,1u);if(slot<${p}_state.capacity){${p}_ids[slot]=id;return true;}atomicAdd(&${p}_state.overflow,1u);return false;}
`;}

/** Spill-aware append contract. Overflow entries are captured immediately in a second queue. */
export function gpuU32OverflowQueueWGSL({group=0,mainIdsBinding=0,mainStateBinding=1,spillIdsBinding=2,spillStateBinding=3,prefix='diagram_secondary'}={}){const p=String(prefix).replace(/[^A-Za-z0-9_]/g,'_');return `
struct ${p}_State{count:atomic<u32>,overflow:atomic<u32>,capacity:u32,_pad:u32};
@group(${group}) @binding(${mainIdsBinding}) var<storage,read_write> ${p}_ids:array<u32>;
@group(${group}) @binding(${mainStateBinding}) var<storage,read_write> ${p}_state:${p}_State;
@group(${group}) @binding(${spillIdsBinding}) var<storage,read_write> ${p}_spill_ids:array<u32>;
@group(${group}) @binding(${spillStateBinding}) var<storage,read_write> ${p}_spill_state:${p}_State;
fn ${p}_count()->u32{return min(atomicLoad(&${p}_state.count),${p}_state.capacity);}
fn ${p}_id(i:u32)->u32{return ${p}_ids[i];}
fn ${p}_push(id:u32)->bool{let slot=atomicAdd(&${p}_state.count,1u);if(slot<${p}_state.capacity){${p}_ids[slot]=id;return true;}atomicAdd(&${p}_state.overflow,1u);let ss=atomicAdd(&${p}_spill_state.count,1u);if(ss<${p}_spill_state.capacity){${p}_spill_ids[ss]=id;return true;}atomicAdd(&${p}_spill_state.overflow,1u);return false;}
`;}

function queueIndirectWGSL(workgroupSize){return `
struct QState{count:atomic<u32>,overflow:atomic<u32>,capacity:u32,_pad:u32};@group(0) @binding(0) var<storage,read_write> state:QState;@group(0) @binding(1) var<storage,read_write> args:array<u32>;
@compute @workgroup_size(1) fn main(){let n=min(atomicLoad(&state.count),state.capacity);args[0]=(n+${workgroupSize-1}u)/${workgroupSize}u;args[1]=1u;args[2]=1u;}`;}

/** Fixed-capacity active-ID queue for particle/history/ray kernels. */
