function normalizeSecondaryOverflowPolicy(value){const p=String(value||'error').toLowerCase().replace(/_/g,'-');if(['error','truncate','spill-to-cpu'].includes(p))return p;throw err(`Unknown secondary overflow policy: ${value}`,'BAD_MC_OVERFLOW_POLICY');}

