  buffer(name){const b=this.buffers.get(String(name));if(!b)throw err(`Unknown GPU tally ${name}`,'UNKNOWN_TALLY');return b;}
  async clear(names=null,{device=null}={}){await this.init({device});const selected=names==null?this.names:(Array.isArray(names)?names:[names]),enc=this.device.createCommandEncoder({label:`${this.label}:clear`});for(const n of selected)enc.clearBuffer(this.buffer(n));this.device.queue.submit([enc.finish()]);if(this.device.queue.onSubmittedWorkDone)await this.device.queue.onSubmittedWorkDone();return this;}
