  const byId=new Map(pipeline.stages.map(s=>[s.id,s])), indeg=new Map(), children=new Map();
  for(const s of pipeline.stages){indeg.set(s.id,s.dependsOn.length);for(const d of s.dependsOn){const a=children.get(d)||[];a.push(s.id);children.set(d,a);}}
