  const n=A.length,m=B[0].length,p=B.length,C=Array.from({length:n},()=>new Array(m).fill(0));
  for(let i=0;i<n;i++)for(let k=0;k<p;k++){const a=A[i][k]; if(a===0)continue; for(let j=0;j<m;j++)C[i][j]+=a*B[k][j];}
  return C;
