  await test('GPU-1: f32 tally variance is two-pass, and an unmeasurable variance reports unknown',async()=>{
    const {rt,device}=await gpuStubRuntime(),n=65536,gt=rt.createGPUF32TallySet({capacity:n,tallies:['dose']});await gt.init({device});
    const f32=b=>new Float32Array(b.data);
    /* faithful f32 stand-ins for the module's own workgroup-256 tree reduction and its two element
     * kernels, so the cancellation of the (sumSq - sum^2/n) identity is reproduced exactly */
    const treeReduce=(src,count,op)=>{let cur=src.slice(0,count);
      while(cur.length>1){const groups=Math.ceil(cur.length/256),out=new Float32Array(groups);
        for(let g=0;g<groups;g++){const s=new Float32Array(256).fill(op==='sum'?0:op==='min'?Infinity:-Infinity);
          for(let i=0;i<256&&g*256+i<cur.length;i++)s[i]=cur[g*256+i];
          for(let stride=128;stride>0;stride>>=1)for(let i=0;i<stride;i++)s[i]=op==='sum'?s[i]+s[i+stride]:op==='min'?Math.min(s[i],s[i+stride]):Math.max(s[i],s[i+stride]);
          out[g]=s[0];}
        cur=out;}
      return cur[0];};
    gt.reduction={reduce:async(b,count,o={})=>treeReduce(f32(b),count,String(o.op||'sum'))};
    gt.ops={shiftedSquare:async(x,shift,out,count)=>{const a=f32(x),o=f32(out);for(let i=0;i<count;i++){const d=Math.fround(a[i]-shift);o[i]=d*d;}},
      product:async(x,y,out,count)=>{const a=f32(x),b2=f32(y),o=f32(out);for(let i=0;i<count;i++)o[i]=a[i]*b2[i];}};
    const write=f=>{const d=f32(gt.buffer('dose'));for(let i=0;i<n;i++)d[i]=f(i);};
    write(i=>1e5+((i%3)-1));
    const s=await gt.summarize('dose',n,{device});
    if(s.resolved!==true)throw new Error(`a +-1 spread around 1e5 is measurable, got ${JSON.stringify(s)}`);
    if(Math.abs(s.variance-2/3)>.02)throw new Error(`variance ${s.variance} is not the true 0.6667 (the f32 identity returns 0 here)`);
    if(!(s.stderr>0)||!(s.relativeError>0))throw new Error('a real variance must give a positive stderr and relative error');
    write(()=>1e5);
    const flat=await gt.summarize('dose',n,{device});
    if(flat.resolved!==false||!Number.isNaN(flat.variance)||!Number.isNaN(flat.stderr)||!Number.isNaN(flat.relativeError))throw new Error(`a spread below f32 resolution must report unknown, got ${JSON.stringify(flat)}`);
    if(!/resolution/.test(flat.reason||''))throw new Error('an unresolved variance must say why');
    gt.dispose();rt.dispose();
  });
