  /* --- 0.33.0 W1-B: face-mask stencil operator (gap 7) --------------------------------------- */

  await test('STENCIL-1: the face-mask assembly is the matrix an independent sparse build gives',async()=>{
    const nx=12,ny=10,nz=8,n=nx*ny*nz,h=0.25,inv=1/(h*h),F=STENCIL_FACE_BITS;
    const solid=new Uint8Array(n),dir=new Uint8Array(n),wall=new Uint8Array(n);
    for(let z=0;z<nz;z++)for(let y=0;y<ny;y++)for(let x=0;x<nx;x++){const i=x+nx*(y+ny*z);
      if(x===5&&y>2&&y<8)solid[i]=1;                         /* a 1-cell internal wall of solids */
      if(x===0)dir[i]|=F.XM;if(x===nx-1)dir[i]|=F.XP;        /* two Dirichlet outer faces */
      if(z===4&&y<4)wall[i]|=F.ZM;                           /* a thin internal wall, no solid cell */
    }
    /* Independent second implementation of cfd.html:832's rules, assembled as an explicit sparse
     * matrix (SparseTriplets/SparseMatrix were validated in 0.32.0 against dense elimination). */
    const T=createSparseTriplets({rows:n,cols:n}),step=[[-1,F.XM,F.XP],[1,F.XP,F.XM],[-nx,F.YM,F.YP],[nx,F.YP,F.YM],[-nx*ny,F.ZM,F.ZP],[nx*ny,F.ZP,F.ZM]];
    const coord=i=>[i%nx,Math.floor(i/nx)%ny,Math.floor(i/(nx*ny))];
    for(let i=0;i<n;i++){
      if(solid[i])continue;const c=coord(i);
      for(let a=0;a<6;a++){const [d,fi,fj]=step[a],axis=a>>1,up=a&1,inside=up?c[axis]<[nx,ny,nz][axis]-1:c[axis]>0,j=i+d;
        if(inside){if(!solid[j]&&!((wall[i]&fi)||(wall[j]&fj))){T.add(i,i,inv);T.add(i,j,-inv);}}
        else if(dir[i]&fi){T.add(i,i,2*inv);}}
    }
    const A=SparseMatrix.fromTriplets(T),lvl=buildFaceMaskLevel({shape:[nx,ny,nz],spacing:h,solid,dirichlet:dir,wallBits:wall});
    if(lvl.scale!==inv)throw new Error(`scale ${lvl.scale} != 1/h^2 ${inv}`);
    /* Structural equality, entry by entry: the 8 bytes/cell must carry the same matrix. */
    const dg=A.diagonal();
    for(let i=0;i<n;i++){
      if(Math.abs(dg[i]-lvl.diagonal[i])>1e-9*Math.max(1,Math.abs(dg[i])))throw new Error(`diagonal ${i}: sparse ${dg[i]} vs mask ${lvl.diagonal[i]}`);
      let off=0;for(let p=A.rowPtr[i];p<A.rowPtr[i+1];p++){const j=A.colIndex[p];if(j===i)continue;off++;
        const d=j-i,a=step.findIndex(s=>s[0]===d);if(a<0)throw new Error(`row ${i} has a neighbour at offset ${d} the 6-face mask cannot express`);
        if(!(lvl.faceMask[i]&step[a][1]))throw new Error(`row ${i} has a coupling to ${j} the face mask does not set`);
        if(Math.abs(A.values[p]+inv)>1e-9)throw new Error(`off-diagonal ${i},${j} is ${A.values[p]}, not -1/h^2`);}
      let bits=0;for(let a=0;a<6;a++)if(lvl.faceMask[i]&step[a][1])bits++;
      if(bits!==off)throw new Error(`cell ${i}: mask sets ${bits} faces, the sparse matrix has ${off} off-diagonals`);
    }
    /* A x through the mask, against A x through the sparse matrix, on 50 random vectors. */
    const applyMask=x=>{const y=new Float64Array(n);for(let i=0;i<n;i++){const d=lvl.diagonal[i];if(d<=0){y[i]=0;continue;}
      let s=0;for(let a=0;a<6;a++)if(lvl.faceMask[i]&step[a][1])s+=x[i+step[a][0]];y[i]=d*x[i]-lvl.scale*s;}return y;};
    let worst=0,scale=0;const rnd=createRandomPlan(20250815).stream(1,'stencil');
    for(let t=0;t<50;t++){const x=new Float64Array(n);for(let i=0;i<n;i++)x[i]=solid[i]?0:rnd.nextSigned();
      const a=A.multiplyVector(x),b=applyMask(x);for(let i=0;i<n;i++){worst=Math.max(worst,Math.abs(a[i]-b[i]));scale=Math.max(scale,Math.abs(a[i]));}}
    if(!(worst<=1e-12*scale))throw new Error(`mask matvec vs sparse matvec: max |Δ| ${worst} against scale ${scale}`);
    /* Symmetry and definiteness, from the mask expansion, not from the sparse copy. */
    let asym=0,mag=0,minQ=Infinity;
    for(let t=0;t<100;t++){const u=new Float64Array(n),v=new Float64Array(n);
      for(let i=0;i<n;i++){u[i]=solid[i]?0:rnd.nextSigned();v[i]=solid[i]?0:rnd.nextSigned();}
      const Au=applyMask(u),Av=applyMask(v);let a=0,b=0,q=0,uu=0;
      for(let i=0;i<n;i++){a+=Au[i]*v[i];b+=u[i]*Av[i];q+=u[i]*Au[i];uu+=u[i]*u[i];}
      asym=Math.max(asym,Math.abs(a-b));mag=Math.max(mag,Math.abs(a));if(uu>0)minQ=Math.min(minQ,q/uu);}
    if(!(asym<=1e-12*mag))throw new Error(`<Ax,y> - <x,Ay> reached ${asym} against scale ${mag}`);
    if(!(minQ>0))throw new Error(`<x,Ax> went non-positive (min Rayleigh quotient ${minQ}) on a domain with Dirichlet faces`);
  });
  await test('STENCIL-3: Dirichlet weight 2 is second order and weight 1 provably is not',async()=>{
    const F=STENCIL_FACE_BITS,run=async(N,weight)=>{
      const h=1/N,n=N*N*N,lvl=buildFaceMaskLevel({shape:[N,N,N],spacing:h,dirichlet:true,dirichletWeight:weight}),sy=N,sz=N*N;
      const apply=(x,y)=>{for(let i=0;i<n;i++){const d=lvl.diagonal[i];if(d<=0){y[i]=0;continue;}const o=lvl.faceMask[i];let s=0;
        if(o&F.XM)s+=x[i-1];if(o&F.XP)s+=x[i+1];if(o&F.YM)s+=x[i-sy];if(o&F.YP)s+=x[i+sy];if(o&F.ZM)s+=x[i-sz];if(o&F.ZP)s+=x[i+sz];
        y[i]=d*x[i]-lvl.scale*s;}};
      const b=new Float64Array(n),exact=new Float64Array(n),P=Math.PI,di=new Float64Array(n);
      for(let z=0;z<N;z++)for(let y=0;y<N;y++)for(let x=0;x<N;x++){const i=x+N*(y+N*z),u=Math.sin(P*(x+.5)*h)*Math.sin(P*(y+.5)*h)*Math.sin(P*(z+.5)*h);exact[i]=u;b[i]=3*P*P*u;}
      for(let i=0;i<n;i++)di[i]=lvl.diagonal[i]>0?1/lvl.diagonal[i]:0;
      const r=await solveConjugateGradient({b,x:new Float64Array(n),apply,precondition:(rr,zz)=>{for(let i=0;i<n;i++)zz[i]=di[i]*rr[i];},relativeTolerance:1e-12,maxIterations:4000,cooperativeYield:false});
      if(!r.converged)throw new Error(`the reference solve did not converge at N=${N}, weight ${weight} (${r.reason})`);
      let e=0;for(let i=0;i<n;i++)e=Math.max(e,Math.abs(r.x[i]-exact[i]));return e;};
    const e16=await run(16,2),e32=await run(32,2),order=Math.log2(e16/e32);
    if(!(Math.abs(order-2)<=0.05))throw new Error(`Dirichlet weight 2: max-norm error ${e16.toExponential(3)} -> ${e32.toExponential(3)} is order ${order.toFixed(3)}, not 2.00±0.05`);
    const f16=await run(16,1),f32=await run(32,1),first=Math.log2(f16/f32);
    if(!(first<1.3))throw new Error(`weight 1 must lose an order (the mirror is p_ghost=-p_i, not p_ghost=0); observed order ${first.toFixed(3)}`);
    if(!(f32>10*e32))throw new Error(`weight 1 at N=32 gives ${f32.toExponential(3)} against ${e32.toExponential(3)} for weight 2; the first-order scheme is not distinguishable, so this test proves nothing`);
  });
