    if(Math.abs(got.rz-Math.sqrt(Math.max(0,got.rr)))>1e-5)throw new Error(`sqrt slot ${got.rz} vs ${Math.sqrt(Math.max(0,got.rr))}`);
    sc.dispose();rt.dispose();
