        await sc.op('divide',{out:'alpha',num:'rz',den:'dAd'},o);
        await ops.axpyFromSlot(xB,pB,sc,'alpha',+1,n,o);
        await ops.axpyFromSlot(rB,ApB,sc,'alpha',-1,n,o);
        await ops.dotInto(rB,rB,sc,'rzNew',n,o);
        await sc.op('divide-assign',{out:'beta',num:'rzNew',den:'rz'},o);
