    device.queue.writeBuffer(xB,0,x0);device.queue.writeBuffer(bB,0,b0);
    const rel=(got,want)=>{let e=0,s=0;for(let i=0;i<n;i++){e=Math.max(e,Math.abs(got[i]-want[i]));s=Math.max(s,Math.abs(want[i]));}return e/Math.max(s,1e-30);};
