    if(cu.describe().colourStorageBytes!==16)throw new Error('a custom colouring must report the storage it costs');
    if(cb.colourOrder('forward').join()!=='0,1'||cb.colourOrder('reverse').join()!=='1,0')throw new Error('reverse order is what makes the post-smooth symmetric');
