  await test('VEC-ALIAS: an output that aliases an input is refused instead of returning zeros',async()=>{
    const {rt,device}=await gpuStubRuntime(),ops=rt.createGPUF32VectorOps();
    const U=GPU_USAGE.STORAGE|GPU_USAGE.COPY_SRC|GPU_USAGE.COPY_DST,a=device.createBuffer({size:64,usage:U}),b=device.createBuffer({size:64,usage:U});
    /* Measured on llvmpipe: scale(x, 2, x) produces a buffer of zeros and raises nothing anywhere.
     * WebGPU forbids reading a buffer the same dispatch writes; the failure is silent, so it is the
     * exact class this file refuses to ship. */
    const grab=async fn=>{try{await fn();return null;}catch(e){return e.code;}};
    if(await grab(()=>ops.scale(a,2,a,16,{device}))!=='BAD_VECTOR_OUTPUT')throw new Error('scale(x,a,x) must throw');
    if(await grab(()=>ops.copy(a,a,16,{device}))!=='BAD_VECTOR_OUTPUT')throw new Error('copy(x,x) must throw');
    if(await grab(()=>ops.combine(a,1,a,1,b,16,{device}))!=='BAD_VECTOR_OUTPUT')throw new Error('combine writing one of its inputs must throw');
    if(await grab(()=>ops.axpy(b,1,a,b,16,{device}))!=='BAD_VECTOR_OUTPUT')throw new Error('axpy into one of its inputs must throw; axpyInPlace is the in-place form');
    if(await grab(()=>ops.axpyInPlace(b,1,a,16,{device}))!==null)throw new Error('the in-place form must still be allowed');
    rt.dispose();
  });

  /* A masked geometric-multigrid Poisson problem assembled exactly the way a cfd port would: masked
   * hierarchy (gap 18) -> per-level face-mask stencil (gap 7) -> coloured smoother (gap 6a), with the
   * masked restriction/prolongation that skip cells whose diagonal is non-positive. The V-cycle is
   * written here rather than in the runtime because solveGPUGeometricMultigrid gaining a `smoother`
   * argument is wave 3-A's item, not this one. */
  const buildMaskedPoissonGPU=async(rt,device,{shape,spacing,solid=null,minExtent=4,rule='all'})=>{
    const U=GPU_USAGE.STORAGE|GPU_USAGE.COPY_SRC|GPU_USAGE.COPY_DST,owned=[];
    const mk=n=>{const b=device.createBuffer({size:Math.max(16,n*4),usage:U});owned.push(b);return b;};
    const hier=createGridMultigridHierarchy({topology:{shape,spacing:[spacing,spacing,spacing]},minExtent,minCoarseCells:1,
      masks:solid?{solid:{data:solid,rule}}:{},
      operator:(level,ctx)=>{
        const lvl=buildFaceMaskLevel({shape:ctx.shape,spacing:ctx.spacing[0],solid:ctx.masks.solid||null,dirichlet:true});
        const st=rt.createStencilOperator({topology:{shape:ctx.shape,spacing:ctx.spacing},diagonal:lvl.diagonal,faceMask:lvl.faceMask,scale:lvl.scale,workgroupSize:64,label:`selftest-level-${level}`});
        const d=mk(ctx.cells);device.queue.writeBuffer(d,0,lvl.diagonal);
        const f=mk(ctx.cells);device.queue.writeBuffer(f,0,lvl.faceMask);
        st.cpuLevel=lvl;st.diagonal=d;st.faceMask=f;return st;}});
    const stencils=hier.operators(),counts=hier.levels.map(g=>g.cellCount),depth=hier.depth,N=counts[0];
    const ops=rt.createGPUF32VectorOps(),transfer=rt.createGPUMultigridTransfer(hier);
    const smoother=rt.createGPUColouredSmoother({stencil:l=>stencils[l],sweeps:2,label:'selftest-smoother'});
    const jac=rt.createGPUJacobiPreconditioner({omega:2/3});
    const xs=counts.map(mk),bs=counts.map(mk),rs=counts.map(mk),zs=counts.map(mk);
    const smooth=async(l,k,order,kind,o)=>{
      if(kind==='coloured'){await smoother.apply(l,xs[l],bs[l],{sweeps:k,order,...o});return;}
      for(let s=0;s<k;s++){await stencils[l].residual(xs[l],bs[l],rs[l],o);await jac.apply(rs[l],stencils[l].diagonal,zs[l],counts[l],{...o,omega:2/3});await ops.axpyInPlace(xs[l],1,zs[l],counts[l],o);}};
    const vcycle=async(kind,o,{nu1=2,nu2=2,coarse=50,postOrder='reverse'}={})=>{
      for(let l=0;l<depth;l++){const last=l===depth-1;
        await smooth(l,last?coarse:nu1,'forward',kind,o);
        if(last)break;
        await stencils[l].residual(xs[l],bs[l],rs[l],o);
        await transfer.restrict(rs[l],bs[l+1],l,{...o,diagonal:stencils[l+1].diagonal});
        await ops.fill(xs[l+1],0,counts[l+1],o);}
      for(let l=depth-2;l>=0;l--){await transfer.prolongateAdd(xs[l+1],xs[l],l,{...o,diagonal:stencils[l].diagonal});await smooth(l,nu2,postOrder,kind,o);}};
    /* M^-1 r: one V-cycle from a zero initial guess, which is what makes M a fixed linear operator. */
    const precondition=async(kind,r,z,o,cfg)=>{await ops.copy(r,bs[0],N,o);await ops.fill(xs[0],0,N,o);await vcycle(kind,o,cfg);await ops.copy(xs[0],z,N,o);};
    /* One V-cycle with b = 0 from the given error: exactly the error-propagation operator, whose
     * asymptotic growth factor is what a smoother is judged on. */
    const errorPropagate=async(kind,src,dst,o,cfg)=>{await ops.copy(src,xs[0],N,o);await ops.fill(bs[0],0,N,o);await vcycle(kind,o,cfg);await ops.copy(xs[0],dst,N,o);};
    return {hier,stencils,counts,depth,N,ops,transfer,smoother,vcycle,precondition,errorPropagate,mk,
      dispose(){for(const b of owned)try{b.destroy();}catch{}smoother.dispose();}};
  };

  await test('MG-SMOOTH-2: cfd\'s own <=20-iteration MGPCG gate on 1-voxel walls, inside the runtime',async()=>{
    const c=await probeComputeCapabilities(options);if(!c.webgpu.adapterAvailable)return {skipped:true,reason:'no WebGPU adapter on this platform: the smoother gate cannot be measured here'};
    const rt=await ComputeRuntime.create({benchmark:false}),device=await rt.getGPUDevice();
    const dim=[48,48,16],N=dim[0]*dim[1]*dim[2],solid=cfdRoomMask(...dim);
    const P=await buildMaskedPoissonGPU(rt,device,{shape:dim,spacing:0.5,solid,minExtent:4});
    if(P.depth!==3)throw new Error(`the hierarchy must be cfd's three levels, got ${P.depth}`);
    const f=cfdNoise(N,solid);
    const run=async(kind,Q)=>{const o={device,awaitDone:false},bBuf=Q.mk(N);device.queue.writeBuffer(bBuf,0,f);
      const res=await solveGPUConjugateGradient(rt,{b:bBuf,count:N,device,maxIterations:60,relativeTolerance:1e-6,checkEvery:1,residualPolicy:'recursive-then-verify',
        apply:async(inp,out)=>{await Q.stencils[0].applyA(inp,out,o);},
        precondition:async(r,z)=>{await Q.precondition(kind,r,z,o);}});
      res.dispose();return res;};
    const rb=await run('coloured',P),jac=await run('jacobi',P);
    /* This is cfd.html:8873 verbatim: r.iters > 0 && r.iters <= 20 on 48x48x16 roomMask, tol 1e-6. */
    if(!(rb.iterations>0&&rb.iterations<=20&&rb.converged))
      throw new Error(`the coloured smoother took ${rb.iterations} MGPCG iterations (converged=${rb.converged}, ${rb.reason}); cfd's gate is >0 and <=20`);
    /* The half that says why the feature exists. Measured here: coloured 9, damped Jacobi 13 — so
     * Jacobi does NOT fail this gate, contradicting the scope document, and the assertion is the true
     * claim (strictly fewer iterations at the same sweep count) rather than the convenient one. */
    if(!(rb.iterations<jac.iterations))
      throw new Error(`the coloured smoother (${rb.iterations} iterations) must beat damped Jacobi (${jac.iterations}) at the same sweep count, or it is not worth its own kernel`);
    if(!(rb.relativeResidual<=1e-6))throw new Error(`converged was claimed at a verified true relative residual of ${rb.relativeResidual}`);
    /* MG-MASK-3, end to end: the same solve with the naive coarsening rule. 'any' closes the 1-voxel
     * doorway on the coarse grid — measured 11 iterations instead of 9, and 23 instead of 13 for
     * Jacobi, which is outside cfd's gate. That is what says gap 18 was a real gap and not
     * bookkeeping. */
    const Q=await buildMaskedPoissonGPU(rt,device,{shape:dim,spacing:0.5,solid,minExtent:4,rule:'any'});
    const rbAny=await run('coloured',Q),jacAny=await run('jacobi',Q);
    if(!(rbAny.iterations>rb.iterations))throw new Error(`the 'any' coarsening rule cost ${rbAny.iterations} iterations against 'all' at ${rb.iterations}; if they agree the rule choice is not doing anything and gap 18 is not real here`);
    if(!(jacAny.iterations>20))throw new Error(`with 'any' coarsening the Jacobi-smoothed solve took ${jacAny.iterations} iterations; it is supposed to fall outside cfd's <=20 gate, which is what shows the rule matters`);
    if(Q.hier.describe().masks.solid.coarseFraction[1]<=P.hier.describe().masks.solid.coarseFraction[1])
      throw new Error("'any' must leave MORE solid on the coarse level than 'all'; the fractions say otherwise");
    Q.dispose();P.dispose();rt.dispose();
  });

  await test('MG-SMOOTH-1: the V-cycle contraction factor, measured by power iteration against a CPU f64 reference',async()=>{
    const c=await probeComputeCapabilities(options);if(!c.webgpu.adapterAvailable)return {skipped:true,reason:'no WebGPU adapter on this platform: the contraction factor cannot be measured here'};
    const rt=await ComputeRuntime.create({benchmark:false}),device=await rt.getGPUDevice();
    const n=32,N=n*n*n,P=await buildMaskedPoissonGPU(rt,device,{shape:[n,n,n],spacing:1/n,minExtent:4});
    const e=P.mk(N),e2=P.mk(N),o={device,awaitDone:false};
    let s=31337;const seed=new Float32Array(N);for(let i=0;i<N;i++){s=(Math.imul(s,1103515245)+12345)&0x7fffffff;seed[i]=s/0x7fffffff-0.5;}
    const factor=async kind=>{device.queue.writeBuffer(e,0,seed);let rho=0;
      for(let k=0;k<10;k++){const nrm=await P.ops.norm2(e,N,{device});if(!(nrm>0))break;
        await P.ops.scale(e,1/nrm,e2,N,o);
        await P.errorPropagate(kind,e2,e,o);
        rho=await P.ops.norm2(e,N,{device});}
      return rho;};
    const coloured=await factor('coloured'),jacobi=await factor('jacobi');
    /* The external reference is the same algorithm written in f64 on the CPU, whose asymptotic
     * factors on this problem are 0.1054 (red-black GS) and 0.9622 (damped Jacobi, omega 2/3). Ten
     * power steps on the device measured 0.0909 and 0.8638 — both still climbing towards those
     * values, which is why the Jacobi assertion is a lower bound rather than an equality. */
    if(!(coloured<=0.2))throw new Error(`the coloured smoother's V-cycle contraction factor is ${coloured.toFixed(4)}; a red-black-smoothed V-cycle on a uniform 32^3 Dirichlet cube must be <= 0.2 (CPU f64 reference: 0.1054)`);
    if(!(jacobi>=0.4))throw new Error(`damped Jacobi measured ${jacobi.toFixed(4)} on the same operator; if it is that good the comparison no longer justifies a separate kernel (CPU f64 reference: 0.9622)`);
    if(!(Math.abs(coloured-0.105)<0.05))throw new Error(`the device f32 factor ${coloured.toFixed(4)} disagrees with the independent CPU f64 value 0.1054 by more than 0.05`);
    if(!(jacobi>coloured*4))throw new Error(`the two factors are ${coloured.toFixed(4)} and ${jacobi.toFixed(4)}; the smoother comparison has stopped discriminating`);
    P.dispose();rt.dispose();
  });

  await test('MG-SMOOTH-3: reversed post-smoothing is what makes the preconditioner symmetric',async()=>{
    const c=await probeComputeCapabilities(options);if(!c.webgpu.adapterAvailable)return {skipped:true,reason:'no WebGPU adapter on this platform: preconditioner symmetry cannot be measured here'};
    const rt=await ComputeRuntime.create({benchmark:false}),device=await rt.getGPUDevice();
    const n=16,N=n*n*n,P=await buildMaskedPoissonGPU(rt,device,{shape:[n,n,n],spacing:1/n,minExtent:4});
    const o={device,awaitDone:false},uB=P.mk(N),vB=P.mk(N),MuB=P.mk(N),MvB=P.mk(N);
    const rnd=sd=>{let s=sd>>>0;const f=new Float32Array(N);for(let i=0;i<N;i++){s=(Math.imul(s,1103515245)+12345)&0x7fffffff;f[i]=s/0x7fffffff-0.5;}return f;};
    const asymmetry=async postOrder=>{let worst=0,scale=0;
      for(let t=0;t<6;t++){
        device.queue.writeBuffer(uB,0,rnd(1000+t));device.queue.writeBuffer(vB,0,rnd(5000+t));
        await P.precondition('coloured',uB,MuB,o,{postOrder});await P.precondition('coloured',vB,MvB,o,{postOrder});
        const a=await P.ops.dot(uB,MvB,N,{device}),b=await P.ops.dot(MuB,vB,N,{device});
        worst=Math.max(worst,Math.abs(a-b));scale=Math.max(scale,Math.abs(a),Math.abs(b));}
      return worst/Math.max(scale,1e-30);};
    const symmetric=await asymmetry('reverse'),broken=await asymmetry('forward');
    /* Measured: 2.2e-7 with the reversed post-smooth (f32 round-off, ~2 ulp of the inner product) and
     * 1.5e-2 with a forward post-smooth. cfd.html:1167 says reversing the colour order is what makes
     * M symmetric; both halves of that sentence are asserted here, so a future "simplification" of
     * that line fails a test instead of quietly costing PCG its conjugacy. */
    if(!(symmetric<1e-5))throw new Error(`<u,M v> and <M u, v> differ by ${symmetric.toExponential(2)} relative with reversed post-smoothing; f32 round-off is ~2e-7`);
    if(!(broken>1e-4))throw new Error(`a forward post-smooth measured ${broken.toExponential(2)} relative asymmetry; if it is symmetric too, this test no longer shows why the colour order is reversed`);
    if(!(broken>symmetric*100))throw new Error(`the asymmetry gap is only ${(broken/symmetric).toFixed(1)}x`);
    P.dispose();rt.dispose();
  });

  await test('GPU-SMOOTH-WGSL: the generated coloured sweep is the operator\'s own relax, and every colouring agrees',async()=>{
    const c=await probeComputeCapabilities(options);if(!c.webgpu.adapterAvailable)return {skipped:true,reason:'no WebGPU adapter on this platform: the generated WGSL cannot be executed here'};
    const rt=await ComputeRuntime.create({benchmark:false}),device=await rt.getGPUDevice(),F=STENCIL_FACE_BITS;
    const nx=12,ny=10,nz=8,n=nx*ny*nz,h=0.25,U=GPU_USAGE.STORAGE|GPU_USAGE.COPY_SRC|GPU_USAGE.COPY_DST;
    const solid=new Uint8Array(n),dir=new Uint8Array(n);
    for(let z=0;z<nz;z++)for(let y=0;y<ny;y++)for(let x=0;x<nx;x++){const i=x+nx*(y+ny*z);
      if(x===5&&y>2&&y<8)solid[i]=1;if(x===0)dir[i]|=F.XM;if(x===nx-1)dir[i]|=F.XP;}
    const lvl=buildFaceMaskLevel({shape:[nx,ny,nz],spacing:h,solid,dirichlet:dir});
    const st=rt.createStencilOperator({topology:{shape:[nx,ny,nz],spacing:h},diagonal:lvl.diagonal,faceMask:lvl.faceMask,scale:lvl.scale,workgroupSize:64});
    const x0=new Float32Array(n),b0=new Float32Array(n);
    for(let i=0;i<n;i++){x0[i]=solid[i]?0:Math.sin(i*0.37)*(1+(i%3));b0[i]=solid[i]?0:Math.cos(i*0.11);}
    const mk=()=>device.createBuffer({size:n*4,usage:U}),xA=mk(),xB=mk(),xC=mk(),bBuf=mk();
    device.queue.writeBuffer(bBuf,0,b0);
    for(const buf of [xA,xB,xC])device.queue.writeBuffer(buf,0,x0);
    /* the operator's own relax, red then black */
    await st.relax(xA,bBuf,{device,colour:0});await st.relax(xA,bBuf,{device,colour:1});
    const smoother=rt.createGPUColouredSmoother({stencil:st,sweeps:1});
    await smoother.apply(0,xB,bBuf,{device,sweeps:1,order:'forward'});
    const gotA=await readbackGPUF32(device,xA,n),gotB=await readbackGPUF32(device,xB,n);
    /* Bit-for-bit: the smoother's kernel is generated from the same prelude and computes the same
     * expression in the same order. Anything else means the two have drifted apart. */
    for(let i=0;i<n;i++)if(!Object.is(gotA[i],gotB[i]))throw new Error(`the generated sweep differs from StencilOperator.relax at cell ${i}: ${gotB[i]} vs ${gotA[i]}`);
    /* an explicit colour array holding the same checkerboard must give the same answer */
    const colours=new Uint32Array(n);
    for(let z=0;z<nz;z++)for(let y=0;y<ny;y++)for(let x=0;x<nx;x++)colours[x+nx*(y+ny*z)]=(x+y+z)&1;
    const custom=rt.createGPUColouredSmoother({stencil:st,sweeps:1,colouring:{colourOf:colours,colours:2}});
    await custom.apply(0,xC,bBuf,{device,sweeps:1,order:'forward'});
    const gotC=await readbackGPUF32(device,xC,n);
    for(let i=0;i<n;i++)if(!Object.is(gotA[i],gotC[i]))throw new Error(`the custom colouring differs from the in-shader checkerboard at cell ${i}`);
    for(let i=0;i<n;i++)if(solid[i]&&gotB[i]!==x0[i])throw new Error(`the smoother wrote into solid cell ${i}`);
    /* axis-parity is a real 8-colour Gauss-Seidel: it must reduce the residual, not merely run */
    const xD=mk();device.queue.writeBuffer(xD,0,x0);
    const ap=rt.createGPUColouredSmoother({stencil:st,sweeps:1,colouring:'axis-parity'});
    const rBuf=mk(),ops=rt.createGPUF32VectorOps();
    await st.residual(xD,bBuf,rBuf,{device});const before=await ops.norm2(rBuf,n,{device});
    await ap.apply(0,xD,bBuf,{device,sweeps:3});
    await st.residual(xD,bBuf,rBuf,{device});const after=await ops.norm2(rBuf,n,{device});
    if(!(after<before*0.5))throw new Error(`three axis-parity sweeps reduced the residual only from ${before.toExponential(3)} to ${after.toExponential(3)}`);
    let badColour=null;try{await smoother.sweepColour(0,xB,bBuf,5,{device});}catch(e){badColour=e.code;}
    if(badColour!=='BAD_SMOOTHER')throw new Error('a colour outside the declared range must throw, not dispatch a sweep that touches nothing');
    smoother.dispose();custom.dispose();ap.dispose();rt.dispose();
  });

  await test('MG-INT-1: solveGPUGeometricMultigrid with a smoother reproduces the hand-written V-cycle exactly',async()=>{
    const c=await probeComputeCapabilities(options);if(!c.webgpu.adapterAvailable)return {skipped:true,reason:'no WebGPU adapter on this platform: the assembled V-cycle cannot be executed here'};
    const rt=await ComputeRuntime.create({benchmark:false}),device=await rt.getGPUDevice();
    const n=16,N=n*n*n,P=await buildMaskedPoissonGPU(rt,device,{shape:[n,n,n],spacing:1/n,minExtent:4});
    const o={device,awaitDone:false},rB=P.mk(N),zRT=P.mk(N),zRef=P.mk(N);
    let s=987654321;const f=new Float32Array(N);for(let i=0;i<N;i++){s=(Math.imul(s,1103515245)+12345)&0x7fffffff;f[i]=s/0x7fffffff-0.5;}
    device.queue.writeBuffer(rB,0,f);
    /* The external reference is wave 2's V-cycle, written in this file out of the PUBLIC bricks
     * (stencil.residual, transfer.restrict/prolongateAdd with a diagonal, smoother.apply) — a second
     * implementation, not a call back into the same code. If the solver's assembly differs anywhere —
     * a missing masked transfer, the wrong colour order on the upstroke, a residual computed as
     * apply+combine instead of the operator's own kernel — these two disagree. */
    const M=createGPUMultigridPreconditioner(rt,{hierarchy:P.hier,smoother:P.smoother,cycles:1,coarseIterations:50,device});
    await M(rB,zRT);
    await P.precondition('coloured',rB,zRef,o);
    const a=await readbackGPUF32(device,zRT,N),b=await readbackGPUF32(device,zRef,N);
    let diff=0,scale=0;for(let i=0;i<N;i++){diff=Math.max(diff,Math.abs(a[i]-b[i]));scale=Math.max(scale,Math.abs(b[i]));}
    if(!(diff===0))throw new Error(`the solver's V-cycle differs from the reference by ${diff.toExponential(3)} (scale ${scale.toExponential(3)}); the two run the same kernels in the same order and must agree bit for bit`);
    if(M.lastSmoothing.postOrder!=='reverse'||M.lastSmoothing.order!=='forward')throw new Error(`the preconditioner smoothed ${M.lastSmoothing.order}/${M.lastSmoothing.postOrder}`);
    if(M.lastSmoothing.symmetric!==true)throw new Error('the preconditioner must report a symmetric arrangement');
    if(M.lastSmoothing.coarseSymmetry!=='assumed-near-exact'||!/close to exact/.test(M.lastSmoothing.coarseSymmetryReason))
      throw new Error(`the forward-only coarse solve is an ASSUMPTION and the result has to say so, got ${M.lastSmoothing.coarseSymmetry}: ${M.lastSmoothing.coarseSymmetryReason}`);
    /* apply and diagonal come from the hierarchy when the caller supplies neither */
    const res=await solveGPUGeometricMultigrid(rt,{hierarchy:P.hier,smoother:P.smoother,b:rB,count:N,device,maxCycles:2,coarseIterations:50,relativeTolerance:1e-4});
    if(res.operatorSource!=='hierarchy face-mask stencil operators')throw new Error(`operatorSource ${res.operatorSource}`);
    if(res.transfer.masked!==true)throw new Error('a hierarchy with per-level operators must transfer with the diagonal test by default');
    res.dispose();
    /* and a hierarchy WITHOUT an operator still needs an apply, loudly */
    let missing=null;try{await solveGPUGeometricMultigrid(rt,{grid:{shape:[8,8,8]},b:new Float32Array(512),device});}catch(e){missing=e.code;}
    if(missing!=='BAD_MULTIGRID')throw new Error(`a hierarchy with no operator and no apply reported ${missing}`);
    P.dispose();rt.dispose();
  });

