    const M=createGPUMultigridPreconditioner(rt,{hierarchy:P.hier,smoother:P.smoother,cycles:1,coarseIterations:50,device});
    const res=await solveGPUConjugateGradient(rt,{b:bBuf,count:N,device,maxIterations:60,relativeTolerance:1e-6,checkEvery:1,residualPolicy:'recursive-then-verify',
      apply:async(i,out)=>{await P.stencils[0].applyA(i,out,o);},precondition:M});
