      throw new Error(`the assembled MGPCG took ${res.iterations} iterations (converged=${res.converged}, ${res.reason}); cfd's gate is >0 and <=20`);
    if(!(res.relativeResidual<=1e-6))throw new Error(`converged claimed at a verified true relative residual of ${res.relativeResidual}`);
    res.dispose();
