    const N=16,n=N*N*N,h=1/N,PI=Math.PI,U=GPU_USAGE.STORAGE|GPU_USAGE.COPY_SRC|GPU_USAGE.COPY_DST;
    const lvl=buildFaceMaskLevel({shape:[N,N,N],spacing:h,dirichlet:true});
    const st=rt.createStencilOperator({topology:{shape:[N,N,N],spacing:h},diagonal:lvl.diagonal,faceMask:lvl.faceMask,scale:lvl.scale});
    const b=new Float32Array(n),exact=new Float64Array(n);
    for(let z=0;z<N;z++)for(let y=0;y<N;y++)for(let x=0;x<N;x++){const i=x+N*(y+N*z),u=Math.sin(PI*(x+.5)*h)*Math.sin(PI*(y+.5)*h)*Math.sin(PI*(z+.5)*h);exact[i]=u;b[i]=3*PI*PI*u;}
    const bBuf=device.createBuffer({size:n*4,usage:U});device.queue.writeBuffer(bBuf,0,b);
    /* An unreachable tolerance so every run performs exactly 30 iterations and the comparison is of
     * the iterate, not of when each run happened to stop. */
    const solve=async extra=>{const o={device,awaitDone:false};
      const res=await solveGPUConjugateGradient(rt,{b:bBuf,count:n,device,maxIterations:30,relativeTolerance:1e-30,readback:true,
        apply:async(inp,out)=>{await st.applyA(inp,out,o);},...extra});
      return res;};
    const one=await solve({checkEvery:1,residualPolicy:'recursive-then-verify'});
    const ten=await solve({checkEvery:10,residualPolicy:'recursive-then-verify'});
    const enc=await solve({checkEvery:10,residualPolicy:'recursive-then-verify',encoded:true,
      applyEncoded:async(inp,out,ctx)=>{await st.applyA(inp,out,{device,encoder:ctx.encoder,scope:ctx.scope});}});
    if(one.iterations!==30||ten.iterations!==30||enc.iterations!==30)throw new Error(`iteration counts ${one.iterations}/${ten.iterations}/${enc.iterations}`);
    for(let i=0;i<n;i++){
      if(!Object.is(one.x[i],ten.x[i]))throw new Error(`checkEvery:10 diverged from checkEvery:1 at cell ${i}: ${ten.x[i]} vs ${one.x[i]} — the arithmetic per iteration must be identical, only the reads differ`);
      if(!Object.is(one.x[i],enc.x[i]))throw new Error(`the single-encoder replay diverged from the per-op replay at cell ${i}: ${enc.x[i]} vs ${one.x[i]}`);}
    if(!Object.is(one.residual,ten.residual)||!Object.is(one.residual,enc.residual))throw new Error(`the verified true residual differs: ${one.residual} / ${ten.residual} / ${enc.residual}`);
    if(one.checks!==30||ten.checks!==3||enc.checks!==3)throw new Error(`check counts ${one.checks}/${ten.checks}/${enc.checks}`);
    /* And against the 0.32.x path, whose alpha/beta are divided on the CPU in f64 rather than on the
     * device in f32: the same iteration count and the same iterate to f32 accumulation. */
    const legacy=await solveGPUConjugateGradient(rt,{b:bBuf,count:n,device,maxIterations:30,relativeTolerance:1e-30,readback:true,
      apply:async(inp,out)=>{await st.applyA(inp,out,{device,awaitDone:false});}});
    let worst=0,scale=0;for(let i=0;i<n;i++){worst=Math.max(worst,Math.abs(legacy.x[i]-one.x[i]));scale=Math.max(scale,Math.abs(legacy.x[i]));}
    if(!(worst/Math.max(scale,1e-30)<1e-3))throw new Error(`the slot path drifted from the CPU-scalar path by ${(worst/scale).toExponential(2)} relative after 30 iterations; f32 accumulation should be far below 1e-3`);
    for(const r of [one,ten,enc,legacy])r.dispose();
