    if(loose.iterations%8!==0)throw new Error(`with checkEvery:8 the detection iteration must be a multiple of 8, got ${loose.iterations}`);
    if(!(loose.iterations>=tight.iterations))throw new Error('deferred detection cannot be earlier than immediate detection');
