      throw new Error(`overshoot ${loose.overshootIterations} does not equal detection ${loose.iterations} minus the true convergence iteration ${tight.iterations}; the history buffer is not measuring what it claims`);
    if(!(loose.overshootIterations>0))throw new Error(`this problem must actually overshoot with checkEvery:8, or the accounting is untested (detected ${loose.iterations}, converged ${tight.iterations})`);
    if(loose.detectedAtIteration!==loose.iterations)throw new Error('detectedAtIteration must be the iteration the check fired at');
    /* converged is still gated on the verified true residual, not on the recursive one */
