    if(!(loose.relativeResidual<=1e-5))throw new Error(`converged was claimed at a true relative residual of ${loose.relativeResidual}`);
    if(!(loose.recursiveRelativeResidual<=1e-5))throw new Error('the recursive residual must also be reported');
