  /* ---------- WASM engine, shared payloads, array tallies (gaps 10, 11) ----------
   * The module the first three cases run on is assembled BYTE BY BYTE here, not fetched: the runtime
   * must not depend on a 126 kB artifact to prove itself, and a module built in the test is an
   * independent reference in the strictest sense — its arithmetic is defined by the WebAssembly
   * specification and not by anything in this file. It exports memory, a bump `alloc`, `grow`, and
   * `dot(ptrA, ptrB, len) -> f64` summing a[i]*b[i] in exactly the order fieldDot does. */
  const assembleTestModule=()=>{
    const u=n=>{const o=[];let v=n>>>0;do{let b=v&0x7f;v>>>=7;if(v)b|=0x80;o.push(b);}while(v);return o;};
    const str=s=>[...u(s.length),...Array.from(s,c=>c.charCodeAt(0))];
    const sec=(id,body)=>[id,...u(body.length),...body];
    const vec=items=>[...u(items.length),...items.flat()];
    const f64c=v=>{const b=new Uint8Array(8);new DataView(b.buffer).setFloat64(0,v,true);return [0x44,...b];};
    const types=vec([[0x60,...vec([[0x7f],[0x7f],[0x7f]]),...vec([[0x7c]])],[0x60,...vec([[0x7f]]),...vec([[0x7f]])]]);
    const dot=[...vec([[0x01,0x7f],[0x01,0x7c]]),                       // locals: i32 i, f64 acc
      ...f64c(0),0x21,0x04, 0x41,0x00,0x21,0x03, 0x02,0x40, 0x03,0x40,  // acc=0; i=0; block{ loop{
        0x20,0x03,0x20,0x02,0x4e,0x0d,0x01,                             //  if(i>=len) break
        0x20,0x04, 0x20,0x00,0x20,0x03,0x41,0x08,0x6c,0x6a,0x2b,0x03,0x00,
        0x20,0x01,0x20,0x03,0x41,0x08,0x6c,0x6a,0x2b,0x03,0x00,
        0xa2,0xa0,0x21,0x04,                                            //  acc = acc + a[i]*b[i]
        0x20,0x03,0x41,0x01,0x6a,0x21,0x03, 0x0c,0x00, 0x0b,0x0b,       //  i++ } }
      0x20,0x04,0x0b];
    const grow=[0x00, 0x20,0x00,0x40,0x00, 0x0b];                       // memory.grow(pages)
    const alloc=[...vec([[0x01,0x7f]]),
      0x23,0x00,0x22,0x01, 0x20,0x00,0x6a, 0x41,0x07,0x6a, 0x41,0x78,0x71, 0x24,0x00, // bump, 8-aligned
      0x02,0x40,0x03,0x40, 0x23,0x00,0x3f,0x00,0x41,0x10,0x74,0x4d,0x0d,0x01,         // grow until it fits
      0x41,0x01,0x40,0x00,0x1a,0x0c,0x00, 0x0b,0x0b, 0x20,0x01,0x0b];
    const code=vec([dot,grow,alloc].map(b=>[...u(b.length),...b]));
    return new Uint8Array([0,0x61,0x73,0x6d,1,0,0,0,
      ...sec(1,types),...sec(3,vec([[0],[1],[1]])),...sec(5,vec([[0x00,...u(1)]])),
      ...sec(6,vec([[0x7f,0x01,0x41,0x10,0x0b]])),
      ...sec(7,vec([[...str('memory'),0x02,0x00],[...str('dot'),0x00,0x00],[...str('grow'),0x00,0x01],[...str('alloc'),0x00,0x02]])),
      ...sec(10,code)]);
  };
  const testEngineSpec=bytes=>({name:'selftest-dot',source:{bytes},memory:{export:'memory',views:'revalidating'},
    exports:{alloc:'alloc',dot:'dot',grow:'grow'},determinism:'repeatable'});

  await test('WASM-1: an assembled module\'s f64 dot equals fieldDot bit for bit',async()=>{
    if(typeof WebAssembly==='undefined')return {skipped:true,reason:'no WebAssembly on this platform'};
    const bytes=assembleTestModule();
    if(!WebAssembly.validate(bytes))throw new Error('the assembled test module is not a valid WebAssembly binary');
    const rt=await ComputeRuntime.create({benchmark:false});
    try{
      const eng=rt.createWasmEngine({...testEngineSpec(bytes),cache:false}),inst=await eng.instantiate();
      const n=257,a=new Float64Array(n),b=new Float64Array(n);
      for(let i=0;i<n;i++){a[i]=Math.sin(i*0.37)*11.25;b[i]=Math.cos(i*0.113)/3;}
      const [pa]=inst.putF64(a),[pb]=inst.putF64(b);
      const got=inst.call('dot',pa,pb,n),want=fieldDot(a,b);
      if(got!==want)throw new Error(`the module and fieldDot disagree in f64: ${got} vs ${want} (delta ${got-want})`);
      // The bytes really went through the view, not around it.
      const there=inst.view.f64(pa,n);
      for(let i=0;i<n;i++)if(there[i]!==a[i])throw new Error(`alloc/put/view round trip corrupted element ${i}`);
      const copy=inst.view.copyOut.f64(pa,n);
      if(copy.buffer===inst.view.buffer)throw new Error('copyOut handed back a view into instance memory');
      if(copy[7]!==a[7])throw new Error('copyOut returned the wrong bytes');
      if(eng.describe().engine!=='wasm'||eng.describe().simdClaim!=='absent')
        throw new Error(`a module with no 0xfd byte in its code section must report simd 'absent', got ${eng.describe().simdClaim}`);
      const missing=(()=>{try{new WasmInstance(inst.instance,{exports:{nope:'not_exported'}});return 'no error';}catch(e){return e.code;}})();
      if(missing!=='WASM_MISSING_EXPORT')throw new Error(`a missing export must throw WASM_MISSING_EXPORT, got ${missing}`);
    }finally{rt.dispose();}
  });

  await test('WASM-2: views survive memory growth, and a view cached across the call does not',async()=>{
    if(typeof WebAssembly==='undefined')return {skipped:true,reason:'no WebAssembly on this platform'};
    const rt=await ComputeRuntime.create({benchmark:false});
    try{
      const eng=rt.createWasmEngine({...testEngineSpec(assembleTestModule()),cache:false}),inst=await eng.instantiate();
      const n=64,a=new Float64Array(n);for(let i=0;i<n;i++)a[i]=i+0.5;
      const [pa]=inst.putF64(a);
      const stale=inst.view.f64(pa,n);                       // taken BEFORE the growth, cached by hand
      if(stale[3]!==3.5)throw new Error('the pre-growth view did not read the data');
      const growth0=inst.view.stats().growthEvents;
      inst.call('grow',4);                                   // detaches every buffer derived from the old memory
      if(stale.byteLength!==0)throw new Error(`memory.grow() must detach a hand-cached view; byteLength is still ${stale.byteLength}`);
      if(inst.view.stats().growthEvents!==growth0+1)throw new Error('the growth was not counted');
      const fresh=inst.view.f64(pa,n);                       // the engine re-derives instead of handing back the dead one
      if(fresh.byteLength===0)throw new Error('the engine returned a detached view: the re-derivation is missing');
      for(let i=0;i<n;i++)if(fresh[i]!==a[i])throw new Error(`data was lost across growth at ${i}`);
      // A write through the re-derived view must land in the instance, which the module can see.
      const [pb]=inst.putF64(new Float64Array(n).fill(2));
      if(inst.call('dot',pa,pb,n)!==fieldDot(a,new Float64Array(n).fill(2)))throw new Error('a post-growth write did not reach the instance');
      const range=(()=>{try{inst.view.f64(pa,1<<28);return 'no error';}catch(e){return e.code;}})();
      if(range!=='WASM_VIEW_RANGE')throw new Error(`a view past the end of memory must throw WASM_VIEW_RANGE, got ${range}`);
      const align=(()=>{try{inst.view.f64(pa+1,2);return 'no error';}catch(e){return e.code;}})();
      if(align!=='WASM_VIEW_MISALIGNED')throw new Error(`an unaligned zero-copy view must throw WASM_VIEW_MISALIGNED, got ${align}`);
      if(inst.view.copyOut.f64(pa+1,2).length!==2)throw new Error('copyOut must serve the unaligned read the zero-copy view refuses');
    }finally{rt.dispose();}
  });

  await test('WASM-3: one compile serves eight instances, and their memories are independent',async()=>{
    if(typeof WebAssembly==='undefined')return {skipped:true,reason:'no WebAssembly on this platform'};
    const rt=await ComputeRuntime.create({benchmark:false});
    try{
      const cache=new WasmModuleCache({name:'selftest'});
      const eng=rt.createWasmEngine({...testEngineSpec(assembleTestModule()),cache});
      const insts=[];for(let i=0;i<8;i++)insts.push(await eng.instantiate());
      const d=eng.describe();
      if(d.compile.cached!==7)throw new Error(`8 instantiations must compile once and hit the cache 7 times, got cached=${d.compile.cached}`);
      if(cache.stats().compiles!==1)throw new Error(`the cache compiled ${cache.stats().compiles} times`);
      if(d.instances.count!==8)throw new Error('the engine lost track of its instances');
      insts[3].view.u32(64,1).set([0xabcdef01]);
      if(insts[5].view.u32(64,1)[0]!==0)throw new Error('two instances share one linear memory');
      if(insts[3].view.u32(64,1)[0]!==0xabcdef01)throw new Error('the write did not stay in its own instance');
      // A second engine over the same bytes must reuse the same compile, not make a second one.
      const twin=rt.createWasmEngine({...testEngineSpec(assembleTestModule()),cache});
      await twin.instantiate();
      if(cache.stats().compiles!==1)throw new Error('the same bytes compiled twice: the cache is not content-keyed');
      if(twin.describe().compile.cached!==1)throw new Error('the second engine did not report the cache hit');
      const plan=eng.transferPlan();
      if(!['module','bytes'].includes(plan.mode)||!plan.reason)throw new Error('transferPlan must name a mode and a reason');
    }finally{rt.dispose();}
  });

  await test('WASM-4: the shared init payload prices the clone it cannot avoid',async()=>{
    const rt=await ComputeRuntime.create({benchmark:false});
    try{
      const blobs={U235:new Uint8Array(4096).fill(7),H1:new Uint8Array(1024).fill(3)};
      const total=4096+1024;
      const cloned=new SharedInitPayload({name:'xs',blobs,policy:'clone',workers:15}).describe();
      if(cloned.mode!=='clone')throw new Error('policy:\'clone\' must clone');
      if(cloned.bytesPerWorker!==total)throw new Error(`bytesPerWorker ${cloned.bytesPerWorker} is not the measured payload ${total}`);
      if(cloned.totalBytes!==total*15)throw new Error(`the fan-out cost must be counted: ${cloned.totalBytes} for 15 workers of ${total}`);
      if(!cloned.reason)throw new Error('a clone must say why it is a clone');
      // The mode chosen by 'sab-or-clone' must match the platform, computed here independently.
      const sab=typeof SharedArrayBuffer!=='undefined',browsing=typeof globalThis.crossOriginIsolated!=='undefined';
      const expect=(sab&&(!browsing||globalThis.crossOriginIsolated===true))?'sab':'clone';
      const auto=new SharedInitPayload({name:'xs',blobs,workers:15});
      if(auto.describe().mode!==expect)throw new Error(`'sab-or-clone' chose ${auto.describe().mode} where the platform supports ${expect}`);
      if(auto.describe().mode==='sab'&&auto.describe().totalBytes!==total)throw new Error('a shared payload must be counted once, not once per worker');
      if(auto.transferList().length)throw new Error('a payload every worker receives can never be transferred');
      // Round trip through the worker-side attach, in whichever mode this platform gave us.
      const attached=SharedInitPayload.attach(auto.toInitPayload());
      if(attached.U235.length!==4096||attached.U235[0]!==7||attached.H1[3]!==3)throw new Error('the attached blobs are not the ones handed in');
      // 'sab-required' either builds a SAB or refuses with the documented code; never degrades quietly.
      const required=(()=>{try{return new SharedInitPayload({blobs,policy:'sab-required'}).mode;}catch(e){return e.code;}})();
      if(expect==='sab'){if(required!=='sab')throw new Error(`'sab-required' must use a SharedArrayBuffer where one is postable, got ${required}`);}
      else if(required!=='SHARED_MEMORY_UNAVAILABLE')throw new Error(`'sab-required' must throw SHARED_MEMORY_UNAVAILABLE where a SAB cannot be posted, got ${required}`);
      const fromRuntime=rt.createSharedPayload({blobs,policy:'clone'});
      if(fromRuntime.workers!==(rt.capabilities?.cpu?.suggestedWorkers||1))throw new Error('the runtime factory must price against the runtime\'s own worker count');
    }finally{rt.dispose();}
  });

  await test('WASM-5: the engine drives the tool\'s own nsim_core.wasm',async()=>{
    const src=options.wasmModule||options.nsimModule||null;
    if(!src)return {skipped:true,reason:'no external module supplied: pass runComputeSelfTests({wasmModule:{bytes}|{url}}) to exercise the engine against nsim_core.wasm'};
    if(typeof WebAssembly==='undefined')return {skipped:true,reason:'no WebAssembly on this platform'};
    const rt=await ComputeRuntime.create({benchmark:false});
    try{
      const eng=rt.createWasmEngine({name:'nsim-core',source:src,cache:false,determinism:'repeatable',
        exports:{alloc:'nsim_alloc',reset:'nsim_reset',setOptions:'nsim_set_options',clearTallies:'nsim_clear_tallies',
          specPtr:'nsim_spec_ptr',specLen:'nsim_spec_len',meshPtr:'nsim_mesh_ptr',meshLen:'nsim_mesh_len'}});
      const inst=await eng.instantiate();
      inst.call('reset');
      /* nsim_set_options takes a packed f32 record; bins and the mesh shape come back out of the
         module through separate exports, so a correct alloc → view → call chain is observable from
         outside: ask for 137 bins and an 8x6x3 mesh, and the module must report exactly those. */
      const [p,len]=inst.putF32([1,1e-4,1e-3,1e4,0,0,137,1e-10,20,8,6,1,12345,0,3]);
      inst.call('setOptions',p,len);
      if(inst.call('specLen')!==137)throw new Error(`nbins 137 came back as spec_len ${inst.call('specLen')}`);
      if(inst.call('meshLen')!==8*6*3)throw new Error(`an 8x6x3 mesh came back as mesh_len ${inst.call('meshLen')}`);
      inst.call('clearTallies');
      const spec=inst.view.f64(inst.call('specPtr'),137);
      if(spec.length!==137||!spec.every(v=>v===0))throw new Error('the cleared spectrum did not read back as 137 zeros');
      const before=inst.view.stats().growthEvents;
      inst.alloc(40*1024*1024);                       // the module grows its own memory here
      if(inst.view.stats().growthEvents<=before)throw new Error('a growing allocation was not observed');
      if(spec.byteLength!==0)throw new Error('the pre-growth view was expected to be detached');
      if(inst.view.f64(inst.call('specPtr'),137).length!==137)throw new Error('the spectrum was unreadable after the module grew its memory');
      const second=await eng.instantiate();
      if(second.memory===inst.memory)throw new Error('two instances of nsim_core share one memory');
    }finally{rt.dispose();}
  });

  await test('WASM-6: the generated worker source instantiates once and hands the module to the handler',async()=>{
    if(typeof WebAssembly==='undefined')return {skipped:true,reason:'no WebAssembly on this platform'};
    let make=null;
    try{make=new Function('self','postMessage','return 1');}catch{make=null;}
    if(!make)return {skipped:true,reason:'Function() is blocked here (CSP), so generated worker source cannot be executed in-process'};
    const rt=await ComputeRuntime.create({benchmark:false});
    try{
      const eng=rt.createWasmEngine({...testEngineSpec(assembleTestModule()),cache:false});
      const source=createWasmWorkerSource(function(payload,ctx){
        if(!ctx.wasm)throw new Error('ctx.wasm is missing');
        const [pa]=ctx.wasm.putF64(payload.a),[pb]=ctx.wasm.putF64(payload.b);
        return {dot:ctx.wasm.call('dot',pa,pb,payload.a.length),instances:ctx.init.__diagramWasm.mode,shared:ctx.shared?ctx.shared.table[0]:null};
      });
      const scope={onmessage:null},posted=[];
      new Function('self','postMessage',source)(scope,m=>posted.push(m));
      if(typeof scope.onmessage!=='function')throw new Error('the generated worker source did not install a message handler');
      const payload=await eng.workerInitPayload(new SharedInitPayload({blobs:{table:new Uint8Array([42,1,2])},policy:'clone'}).toInitPayload());
      await scope.onmessage({data:{__diagramCompute:STANDARD_WORKER_PROTOCOL,type:'init',id:1,payload}});
      const init=posted.find(m=>m.type==='init-result');
      if(!init?.ok)throw new Error(`the worker failed to instantiate: ${init?.error}`);
      const a=new Float64Array([1.5,-2.25,3.125]),b=new Float64Array([2,4,8]);
      await scope.onmessage({data:{__diagramCompute:STANDARD_WORKER_PROTOCOL,type:'run',id:2,payload:{a,b}}});
      await scope.onmessage({data:{__diagramCompute:STANDARD_WORKER_PROTOCOL,type:'run',id:3,payload:{a,b}}});
      const runs=posted.filter(m=>m.type==='result');
      if(runs.length!==2||!runs[0].ok)throw new Error(`the worker run failed: ${runs[0]?.error}`);
      if(runs[0].result.dot!==fieldDot(a,b))throw new Error(`the worker's module disagrees with fieldDot: ${runs[0].result.dot} vs ${fieldDot(a,b)}`);
      if(runs[1].result.dot!==runs[0].result.dot)throw new Error('the second run did not reuse the instance');
      if(runs[0].result.shared!==42)throw new Error('the shared read-only payload did not reach the worker');
      if(eng.describe().instances.perWorker!==true)throw new Error('workerInitPayload must record that instantiation is per worker');
    }finally{rt.dispose();}
  });

  await test('WRK-10: init payloads and their transfer lists are per worker, never fanned out',async()=>{
    const made=[];
    const pool=new ManagedWorkerPool({size:3,
      initPayload:(index,size)=>({index,size,seeds:new Uint8Array([index,index,index]).buffer}),
      initTransfer:(index,payload)=>[payload.seeds],
      workerFactory:()=>{const w=stubWorker();made.push(w);return w;}});
    await pool.init();
    const inits=made.map(w=>w.posted.find(p=>p.msg.type==='init'));
    if(inits.some(p=>!p))throw new Error('a worker never received its init message');
    if(inits.map(p=>p.msg.payload.index).join(',')!=='0,1,2')throw new Error('every worker received the same init payload');
    const lists=inits.map(p=>p.transfer);
    if(lists.some(t=>!t||t.length!==1))throw new Error('the init transfer list did not reach postMessage');
    if(new Set(lists.map(t=>t[0])).size!==3)throw new Error('the workers shared one transfer list, which the first post would have detached');
    pool.destroy();
    // One array cannot be fanned out; the refusal is at construction, not after the damage.
    const fanout=(()=>{try{new ManagedWorkerPool({size:2,initPayload:{},initTransfer:[new ArrayBuffer(8)],workerFactory:()=>stubWorker()});return 'no error';}catch(e){return e.code;}})();
    if(fanout!=='BAD_TRANSFER_FANOUT')throw new Error(`one shared init transfer list must be refused, got ${fanout}`);
    // A single-worker pool may pass an array: there is nothing to fan out.
    const solo=new ManagedWorkerPool({size:1,initPayload:{x:1},initTransfer:[new ArrayBuffer(8)],workerFactory:()=>stubWorker()});
    await solo.init();solo.destroy();
  });

  await test('TALLY-ARR-1: per-bin means and errors match a brute-force reference and the tool\'s own formula',async()=>{
    const rt=await ComputeRuntime.create({benchmark:false});
    try{
      /* The reference is neutron_transport's own merge-side estimator, written out here:
         a = spec[b]/N;  s = (specSq[b]/N - a*a)/(N-1);  rel = sqrt(s)/a. Nothing in the runtime is
         consulted to produce it, and the per-history samples are kept in plain arrays. */
      const NB=12,N=50000,at=rt.createArrayTally({name:'spectrum',shape:[NB],estimator:'history-variance'});
      const spec=new Float64Array(NB),specSq=new Float64Array(NB);
      let s=987654321>>>0;const rnd=()=>{s=(Math.imul(s,1664525)+1013904223)>>>0;return s/4294967296;};
      const cur=new Float64Array(NB);
      for(let i=0;i<N;i++){
        cur.fill(0);
        const hits=1+Math.floor(rnd()*3);
        for(let k=0;k<hits;k++){const bin=Math.floor(rnd()*NB),v=-Math.log(1-rnd());cur[bin]+=v;at.addHistory(bin,v);}
        at.endHistory();
        for(let b=0;b<NB;b++){spec[b]+=cur[b];specSq[b]+=cur[b]*cur[b];}
      }
      const sm=at.summary();
      let dMean=0,dRel=0;
      for(let b=0;b<NB;b++){
        const a=spec[b]/N,v=(specSq[b]/N-a*a)/(N-1),rel=v>0?Math.sqrt(v)/a:0;
        dMean=Math.max(dMean,Math.abs(sm.mean[b]-a)/Math.max(1e-300,Math.abs(a)));
        dRel=Math.max(dRel,Math.abs(sm.relativeError[b]-rel)/Math.max(1e-300,rel));
      }
      if(!(dMean<=1e-12))throw new Error(`per-bin means differ from the brute-force reference by ${dMean}`);
      if(!(dRel<=1e-12))throw new Error(`per-bin relative errors differ from the tool's estimator by ${dRel}`);
      /* The mean of a uniform bin choice with Exp(1) scores is (hits/NB)*1; check the estimator's own
         claim against the analytic value at 3 standard errors, so a systematic bias cannot hide. */
      for(let b=0;b<NB;b++){
        const expected=2/NB;                       // E[hits] = 2, E[value] = 1, spread over NB bins
        if(Math.abs(sm.mean[b]-expected)>4*sm.stderr[b])throw new Error(`bin ${b} mean ${sm.mean[b]} is more than 4 standard errors from the analytic ${expected}`);
      }
      if(sm.estimator!=='history-variance')throw new Error('the estimator must be named in the result');
      const noEstimator=(()=>{try{new ArrayTally({shape:[4]});return 'no error';}catch(e){return e.code;}})();
      if(noEstimator!=='BAD_ARRAY_TALLY')throw new Error(`an array tally without an explicit estimator must be refused, got ${noEstimator}`);
      const f32acc=(()=>{try{new ArrayTally({shape:[4],estimator:'history-variance',dtype:'f32'});return 'no error';}catch(e){return e.code;}})();
      if(f32acc!=='BAD_ARRAY_TALLY')throw new Error('an f32 accumulator must be refused; only the wire may be f32');
    }finally{rt.dispose();}
  });

  await test('TALLY-ARR-2: a bin that never scored reports mean 0 with a finite error, not E[x | x scored]',async()=>{
    const at=new ArrayTally({name:'sparse',shape:[300],estimator:'history-variance'});
    const N=4000,scored=7;
    for(let i=0;i<N;i++){at.addHistory(scored,2.5);at.endHistory();}
    const sm=at.summary();
    if(sm.mean[scored]!==2.5)throw new Error(`the scoring bin must report its mean, got ${sm.mean[scored]}`);
    for(let b=0;b<300;b++){
      if(b===scored)continue;
      if(sm.mean[b]!==0)throw new Error(`bin ${b} scored nothing and must report mean 0, got ${sm.mean[b]}`);
      if(!Number.isFinite(sm.stderr[b]))throw new Error(`bin ${b} must report a finite standard error, got ${sm.stderr[b]}`);
      if(sm.relativeError[b]!==null)throw new Error(`bin ${b} has a zero mean, so its relative error must be null (unknown), not ${sm.relativeError[b]}`);
      if(!sm.reason[b])throw new Error(`bin ${b} must say why its relative error is unavailable`);
    }
    if(sm.histories!==N)throw new Error('every committed history must count in the denominator of every bin');
    /* The mutation this test exists to catch: dividing by the histories that scored in a bin instead
       of by every history. On this data that turns bin 7 into 2.5 either way but every OTHER bin into
       0/0; here it is shown on a bin that scores in half the histories. */
    const half=new ArrayTally({shape:[2],estimator:'history-variance'});
    for(let i=0;i<1000;i++){if(i%2===0)half.addHistory(0,4);half.endHistory();}
    if(Math.abs(half.summary().mean[0]-2)>1e-12)throw new Error(`a bin scoring in half the histories must report 2, not ${half.summary().mean[0]} — the zero fill is missing if this reads 4`);
  });

  await test('TALLY-ARR-3: merge determinism is reported, never assumed',async()=>{
    const partials=[];
    for(let w=0;w<8;w++){
      const t=new ArrayTally({name:'mesh',shape:[3,4],estimator:'history-variance',partition:w});
      for(let i=0;i<64;i++){t.addAt([i%3,(i+w)%4],Math.sin(i+w)+2);t.endHistory();}
      partials.push(t.raw());
    }
    const forward=ArrayTally.mergeRaw(partials);
    const shuffled=ArrayTally.mergeRaw([...partials].reverse());
    if(forward.determinism!=='repeatable')throw new Error(`a partition-ordered merge is repeatable and must say so, got ${forward.determinism}`);
    for(let b=0;b<12;b++)if(forward.sum[b]!==shuffled.sum[b])throw new Error(`the partition order did not fix the addition order at bin ${b}`);
    if(forward.histories!==8*64)throw new Error('the merge lost histories');
    const unindexed=ArrayTally.mergeRaw(partials.map(p=>({...p,partition:null})));
    if(unindexed.determinism!=='statistical')throw new Error(`a merge in arrival order is not repeatable in f64 and must say 'statistical', got ${unindexed.determinism}`);
    if(!/associative/.test(unindexed.determinismBasis))throw new Error('the reason for the weaker claim must be recorded');
    // f32 on the wire is a real loss and downgrades the claim.
    const wired=partials.map((p,i)=>({...p,sum:Float32Array.from(p.sum),sum2:Float32Array.from(p.sum2),transferDtype:'f32'}));
    const merged=ArrayTally.mergeRaw(wired);
    if(merged.determinism!=='statistical')throw new Error('an f32 wire must downgrade the determinism claim');
    let maxRel=0;
    for(let b=0;b<12;b++)maxRel=Math.max(maxRel,Math.abs(merged.sum[b]-forward.sum[b])/Math.max(1e-300,Math.abs(forward.sum[b])));
    if(!(maxRel<1e-6)||maxRel===0)throw new Error(`the f32 wire must lose a little and only a little: relative loss ${maxRel}`);
    const wrongShape=(()=>{try{forward.mergeRaw({...partials[0],shape:[4,3],size:12});return 'no error';}catch(e){return e.code;}})();
    if(wrongShape!=='ARRAY_TALLY_SHAPE')throw new Error(`a shape mismatch must throw ARRAY_TALLY_SHAPE, got ${wrongShape}`);
    const wrongEstimator=(()=>{try{forward.mergeRaw({...partials[0],estimator:'batch-means'});return 'no error';}catch(e){return e.code;}})();
    if(wrongEstimator!=='ARRAY_TALLY_ESTIMATOR')throw new Error(`merging two estimators must be refused, got ${wrongEstimator}`);
    const open=new ArrayTally({shape:[2],estimator:'history-variance'});open.addHistory(0,1);
    const openCode=(()=>{try{open.raw();return 'no error';}catch(e){return e.code;}})();
    if(openCode!=='ARRAY_TALLY_OPEN_HISTORY')throw new Error(`raw() with an uncommitted history must refuse rather than lose it, got ${openCode}`);
  });

  await test('TALLY-ARR-4: batch-means reports a larger error than history-variance when histories are correlated',()=>{
    const hv=new ArrayTally({name:'c',shape:[2],estimator:'history-variance'});
    const bm=new ArrayTally({name:'c',shape:[2],estimator:'batch-means',batchSize:25});
    const iid=new ArrayTally({name:'i',shape:[1],estimator:'history-variance'});
    const iidB=new ArrayTally({name:'i',shape:[1],estimator:'batch-means',batchSize:25});
    let s=24680>>>0;const rnd=()=>{s=(Math.imul(s,1664525)+1013904223)>>>0;return s/4294967296;};
    for(let batch=0;batch<200;batch++){
      const level=rnd()*10;                     // one draw shared by all 25 histories in the batch
      for(let i=0;i<25;i++){
        const v=level+rnd()*0.05;
        hv.addHistory(0,v);hv.endHistory();
        bm.addHistory(0,v);bm.endHistory();
        const u=rnd()*10;                       // and an uncorrelated control
        iid.addHistory(0,u);iid.endHistory();
        iidB.addHistory(0,u);iidB.endHistory();
      }
    }
    const H=hv.summary(),B=bm.summary(),I=iid.summary(),IB=iidB.summary();
    if(Math.abs(H.mean[0]-B.mean[0])>1e-9)throw new Error('the two estimators must agree on the mean; only the error differs');
    if(!(B.stderr[0]>3*H.stderr[0]))throw new Error(`intra-batch correlation must inflate the batch-means error: ${B.stderr[0]} vs ${H.stderr[0]}`);
    const ratio=IB.stderr[0]/I.stderr[0];
    if(!(ratio>0.5&&ratio<2))throw new Error(`on uncorrelated histories the two estimators must roughly agree, got ratio ${ratio}`);
    if(B.varianceOf!=='one batch mean'||H.varianceOf!=='one history score')throw new Error('each summary must say what its variance is a variance of');
    if(B.batches!==200)throw new Error(`batch bookkeeping is wrong: ${B.batches} batches`);
    const noSize=(()=>{try{new ArrayTally({shape:[2],estimator:'batch-means'});return 'no error';}catch(e){return e.code;}})();
    if(noSize!=='BAD_ARRAY_TALLY')throw new Error('batch-means without a batch size must be refused');
  });

  await test('TALLY-ARR-5: a mesh tally survives a JSON checkpoint and merges inside MonteCarloTallies',async()=>{
    const shape=[6,5,3],size=90;
    const build=(partition)=>{
      const t=new ArrayTally({name:'mesh',shape,estimator:'history-variance',weighted:true,transferDtype:'f64',partition});
      let s=(1000+partition)>>>0;const rnd=()=>{s=(Math.imul(s,1664525)+1013904223)>>>0;return s/4294967296;};
      for(let i=0;i<200;i++){
        const w=0.5+rnd();
        t.addAt([Math.floor(rnd()*6),Math.floor(rnd()*5),Math.floor(rnd()*3)],rnd()*2,w);
        t.endHistory(w);
      }
      return t;
    };
    const live=build(0),raw=live.raw();
    const revived=ArrayTally.fromRaw({},JSON.parse(JSON.stringify(raw)));
    const a=live.summary(),b=revived.summary();
    if(revived.histories!==live.histories||revived.weight!==live.weight)throw new Error('the checkpoint lost the history bookkeeping');
    for(let i=0;i<size;i++){
      if(a.mean[i]!==b.mean[i])throw new Error(`the JSON round trip changed bin ${i}: ${a.mean[i]} vs ${b.mean[i]}`);
      if(!(Object.is(a.stderr[i],b.stderr[i])))throw new Error(`the JSON round trip changed the error at bin ${i}`);
    }
    if(ArrayTally.transferables(raw).length!==2)throw new Error('raw() must expose its buffers for a Worker transfer list');
    // The same records inside MonteCarloTallies, merged through the existing raw/mergeRaw path.
    const defs={leakage:'moments',mesh:{type:'array',shape,estimator:'history-variance',weighted:true}};
    const workers=[0,1,2].map(w=>{
      const T=new MonteCarloTallies(defs),p=build(w);
      const vec=new Float64Array(size);
      for(let i=0;i<40;i++){
        vec.fill(0);vec[(i*7+w)%size]=1+i*0.01;
        T.commitHistory(i%3===0?{leakage:1}:{leakage:1,mesh:vec});
      }
      return T.raw();
    });
    const merged=MonteCarloTallies.fromRaw(defs,JSON.parse(JSON.stringify(workers[0])));
    merged.mergeRaw(JSON.parse(JSON.stringify(workers[1])));
    merged.mergeRaw(JSON.parse(JSON.stringify(workers[2])));
    const snap=merged.snapshot();
    if(snap.mesh.type!=='array')throw new Error('MonteCarloTallies did not keep the array record');
    if(snap.mesh.histories!==120)throw new Error(`the merged mesh must cover every history: ${snap.mesh.histories}`);
    if(snap.leakage.count!==120)throw new Error('the scalar record disagrees with the array record about the run length');
    let sum=0;for(let i=0;i<size;i++)sum+=snap.mesh.mean[i]*120;
    let expect=0;for(let w=0;w<3;w++)for(let i=0;i<40;i++)if(i%3!==0)expect+=1+i*0.01;
    if(Math.abs(sum-expect)>1e-9)throw new Error(`the merged mesh total ${sum} is not the total that was scored ${expect}`);
    /* The zero fill has to survive the merge as well: a bin nothing scored still divides by 120. */
    const untouched=[...snap.mesh.mean].filter(v=>v===0).length;
    if(untouched===0)throw new Error('this fixture is supposed to leave bins unscored');
    if(snap.mesh.reason.filter(Boolean).length<untouched)throw new Error('every unresolved bin must carry a reason');
    /* observe() has no history to attach to, so it is refused rather than half-supported. */
    const obs=(()=>{try{merged.observe('mesh',new Float64Array(size));return 'no error';}catch(e){return e.code;}})();
    if(obs!=='ARRAY_TALLY_OBSERVE')throw new Error(`observe() on an array record must be refused, got ${obs}`);
  });

