  /* ---------- SEL: probing, calibration, cost model, selection ----------
   * SEL-6 must stay the first test in this group that calls benchmarkCompute: it compares the very
   * first (cold) calibration against a warm one, so any earlier benchmark run would warm the loops
   * up and let the old code pass for the wrong reason. */
  const withStorage=async fn=>{
    const store=new Map(),prev=Object.getOwnPropertyDescriptor(globalThis,'localStorage');
    Object.defineProperty(globalThis,'localStorage',{value:{getItem:k=>store.has(k)?store.get(k):null,setItem:(k,v)=>{store.set(k,String(v));},removeItem:k=>{store.delete(k);}},configurable:true});
    try{return await fn(store);}finally{if(prev)Object.defineProperty(globalThis,'localStorage',prev);else delete globalThis.localStorage;}
  };
  const smallBench=(vectorItems=4096)=>({cpu:{samples:2,branchyItems:300,vectorItems,vectorRepeats:1,stencilSide:16,stencilRepeats:1,stencil3DSide:8,stencil3DRepeats:1,sparseItems:512,sparseRepeats:1,reductionItems:512,reductionRepeats:1,particleItems:512,particleRepeats:1,rayItems:300,rayRepeats:1}});

  await test('SEL-6: the CPU calibration warms up before timing, as the WebGPU one already did',async()=>{
    const caps=await probeComputeCapabilities(options);
    const o={cpu:{samples:3,branchyItems:20_000,vectorItems:1<<18,vectorRepeats:3,stencilSide:128,stencilRepeats:3,stencil3DSide:32,stencil3DRepeats:2,sparseItems:1<<14,sparseRepeats:2,reductionItems:1<<18,reductionRepeats:4,particleItems:1<<15,particleRepeats:4,rayItems:20_000,rayRepeats:2}};
    // A wall-clock ratio on a shared machine is noisy, and a flaky case in this suite is worse than
    // no case at all: keep the BEST ratio over a few attempts. Genuinely cold-timed code is slower
    // on every attempt, so the minimum still catches the defect; one descheduled run no longer fails it.
    const best={vector:Infinity,stencil:Infinity,reduction:Infinity};let first=null;
    for(let attempt=0;attempt<3;attempt++){
      const cold=(await benchmarkCompute(caps,{...o,force:true})).backends.cpu;
      const warm=(await benchmarkCompute(caps,{...o,force:true})).backends.cpu;
      first=first||cold;
      for(const w of Object.keys(best))best[w]=Math.min(best[w],cold.workloads[w].ms/warm.workloads[w].ms);
      if(Object.values(best).every(r=>r<=1.6))break;
    }
    for(const w of Object.keys(best)){
      const c=first.workloads[w];
      if(!(c.ms<=c.medianMs+1e-9))throw new Error(`${w}: throughput must come from the fastest sample (${c.ms} ms) not the median (${c.medianMs} ms)`);
      if(!(c.itemsPerSecond>0))throw new Error(`${w}: no throughput recorded`);
      if(best[w]>1.6)throw new Error(`${w}: the first calibration is ${best[w].toFixed(2)}x slower than the same code warm in every attempt, so it is still timing cold code`);
    }
  });

