      if(!(await benchmarkCompute(caps,bad)).cached)throw new Error('a partial profile should still be reused inside its retry window');
      const aged=JSON.parse(store.get(CACHE_KEY));aged.timestamp=Date.now()-PARTIAL_CACHE_MS-1;store.set(CACHE_KEY,JSON.stringify(aged));
      if((await benchmarkCompute(caps,bad)).cached)throw new Error('a transient benchmark failure was still served from the cache; it would stand as a hardware fact for 7 days');
      const status=describeComputeSelection({capabilities:caps,profile:first,options:{},kernels:new Map()},null,{});
