  await test('SEL-11: a device that never computes produces no WebGPU calibration',async()=>{
    /* Emulates the one thing a WebGPU stub cannot do by itself: actually running the vector kernel.
       Without it the benchmark must refuse to report throughput; with it, it must succeed. */
    const emulate=stats=>{const d=stats.dispatches.at(-1);if(!d||d.buffers.length!==4)return;
      const A=new Float32Array(d.buffers[0].data),B=new Float32Array(d.buffers[1].data),C=new Float32Array(d.buffers[2].data);
      const n=Math.min(A.length,B.length,C.length);for(let i=0;i<n;i++)A[i]=Math.fround(Math.fround(A[i]*1.0000001)+Math.fround(Math.fround(B[i]*.25)+C[i]));};
    const build=({computes=false}={})=>{
      const {device,stats}=gpuStub();let pushed=0,popped=0;
      device.pushErrorScope=()=>{pushed++;};device.popErrorScope=async()=>{popped++;return null;};
      if(computes){const encoder=device.createCommandEncoder.bind(device);
        device.createCommandEncoder=d=>{const e=encoder(d),begin=e.beginComputePass.bind(e);
          e.beginComputePass=p=>{const pass=begin(p),dispatch=pass.dispatchWorkgroups.bind(pass);pass.dispatchWorkgroups=(...args)=>{dispatch(...args);emulate(stats);};return pass;};return e;};}
      return {device,stats,scopes:()=>({pushed,popped})};
    };
    const caps={webgpu:{adapterAvailable:true},cpu:{}};
    const opts=d=>({device:d,adapter:{limits:d.limits},items:65536,samples:2,vectorRepeats:2,branchyRepeats:1,stencilRepeats:1,stencil3DRepeats:1,sparseRepeats:1,reductionRepeats:1,particleRepeats:1,rayRepeats:1,transferBytes:4096});
    const blind=build();let code=null;
    try{await benchWebGPUWorkloads(caps,opts(blind.device));}catch(e){code=e.code;}
    if(code!=='WEBGPU_BENCH_UNVERIFIED')throw new Error(`a device that accepts submissions without executing them must not yield throughput, got ${code}`);
    const s=blind.scopes();if(!s.pushed||s.pushed!==s.popped)throw new Error(`error scopes must wrap the benchmark and be balanced: ${s.pushed} pushed, ${s.popped} popped`);
    const real=build({computes:true});
    const profile=await benchWebGPUWorkloads(caps,opts(real.device));
    if(!profile?.validated)throw new Error('a device that does compute must pass the verification');
    if(!(profile.workloads.vector.itemsPerSecond>0))throw new Error('a verified benchmark must still report throughput');
    const lost=build({computes:true});let lostCode=null;
    lost.device.lost=Promise.resolve({reason:'destroyed'});
    await Promise.resolve();
    try{await benchWebGPUWorkloads(caps,opts(lost.device));}catch(e){lostCode=e.code;}
    if(lostCode!=='WEBGPU_BENCH_DEVICE_LOST')throw new Error(`a lost device must abort the benchmark, got ${lostCode}`);
  });

