    const hours=Array.from({length:48},(_,i)=>({hour:i}));
    let cp=null;
    await ens.run('profile',{cases:hours,chunkSize:8,checkpointEvery:8,onCheckpoint:c=>{if(!cp&&c.completed.length>=16)cp=JSON.parse(JSON.stringify(c));}});
    if(!cp||cp.completed.length!==16)throw new Error(`the checkpoint did not capture the first 16 cases: ${cp&&cp.completed.length}`);
    calls=0;
