    if(calls!==32)throw new Error(`resume re-ran ${calls} cases instead of the 32 that were outstanding`);
    if(r.completed!==48||r.resumed!==16)throw new Error(`resumed run reports ${r.completed} completed / ${r.resumed} resumed`);
    if(r.results[3].value!==6||r.results[47].value!==94)throw new Error('resumed results do not carry the original case values');
    let refused=false;
    try{await ens.run('profile',{cases:hours.slice(0,10),resume:cp});}catch(e){refused=e.code==='ENSEMBLE_RESUME_MISMATCH';}
