    if (sel.solves !== 2) throw new Error(`three requests on two columns must cost two solves, got ${sel.solves}`);
    if (Math.abs(sel.entries.get('4,11') - inv[4][11]) > 1e-10) throw new Error('a selected entry disagrees with the dense inverse');
    if (Math.abs(sel.diagonal.get(11) - inv[11][11]) > 1e-10) throw new Error('a selected diagonal entry disagrees with the dense inverse');
