    if (name2 !== 'AbortError') throw new Error(`an aborted Newton solve must throw AbortError, got ${name2}`);
    let name3 = null;
    try { await solveContinuation({ residual: (x, l) => [x[0] * x[0] - 1 - 8 * l], x0: [1], signal: ac.signal }); } catch (e) { name3 = e.name; }
    if (name3 !== 'AbortError') throw new Error(`an aborted continuation must throw AbortError, got ${name3}`);
    let name4 = null;
