  await test('complex precisions declare split c64/c128 storage and refuse a single-array allocation',()=>{
    for(const p of ['c64','c128'])if(!NUMERIC_PRECISIONS.includes(p))throw new Error(`${p} is not a declared numeric precision`);
    if(!isComplexDtype('c64')||!isComplexDtype('C128')||isComplexDtype('f64'))throw new Error('isComplexDtype disagrees with NUMERIC_PRECISIONS');
    const a=allocateComplexField(5,{dtype:'c64'}),b=allocateComplexField(5,{dtype:'c128'});
    if(!(a.re instanceof Float32Array)||!(a.im instanceof Float32Array)||a.re===a.im)throw new Error('c64 must be two distinct Float32Arrays');
    if(!(b.re instanceof Float64Array)||!(b.im instanceof Float64Array))throw new Error('c128 must be two Float64Arrays');
    if(a.re.byteLength+a.im.byteLength!==5*complexDtypeInfo('c64').bytesPerValue)throw new Error('c64 byte count disagrees with bytesPerValue');
    if(b.re.byteLength+b.im.byteLength!==5*complexDtypeInfo('c128').bytesPerValue)throw new Error('c128 byte count disagrees with bytesPerValue');
    /* A complex dtype must not silently become a real array. */
    let code='';try{allocateComputeArray(4,{dtype:'c128'});}catch(e){code=e.code;}
    if(code!=='COMPLEX_DTYPE')throw new Error(`allocateComputeArray('c128') should report COMPLEX_DTYPE, got ${code||'no error'}`);
    /* A real array is usable as a complex field with an exactly-zero imaginary part, with no copy. */
    const real=Float64Array.from([1,2,3]),view=asComplexField(real);
    if(view.re!==real||view.im!==null||!view.realOnly)throw new Error('a real array must be viewable as a complex field without copying');
    if(complexFieldDotU(view,view).re!==14||complexFieldDotU(view,view).im!==0)throw new Error('real-only view arithmetic failed');
    for(let i=0;i<5;i++){b.re[i]=i+1;b.im[i]=-0.5*i;}
    const inter=complexFieldToInterleaved(b),back=complexFieldFromInterleaved(inter);
    if(inter.length!==10||back.length!==5)throw new Error('interleaved round trip has the wrong shape');
    for(let i=0;i<5;i++){
      if(inter[2*i]!==b.re[i]||inter[2*i+1]!==b.im[i])throw new Error(`interleaving put the wrong value at ${i}`);
      if(back.re[i]!==b.re[i]||back.im[i]!==b.im[i])throw new Error(`the interleaved round trip lost value ${i}`);
    }
  });

  await test('complex division stays exact where the naive formula overflows or underflows',()=>{
    /* Reference 1: closed form. (1+2i)/(3-4i) = (1+2i)(3+4i)/25 = (-5+10i)/25 = -0.2+0.4i. */
    const q=complexDiv({re:1,im:2},{re:3,im:-4});
    if(Math.abs(q.re+0.2)>1e-16||Math.abs(q.im-0.4)>1e-16)throw new Error(`(1+2i)/(3-4i) gave ${q.re}${q.im>=0?'+':''}${q.im}i, expected -0.2+0.4i`);
    /* Reference 2: the textbook formula a*conj(b)/|b|^2, written here, on operands it cannot handle.
       z/z = 1 for every finite non-zero z; the naive form gives NaN because |b|^2 leaves the range. */
    const naive=(a,b)=>{const d=b.re*b.re+b.im*b.im;return {re:(a.re*b.re+a.im*b.im)/d,im:(a.im*b.re-a.re*b.im)/d};};
    for(const z of [{re:1e300,im:1e300},{re:1e-320,im:1e-320},{re:1e200,im:-3e200}]){
      const ours=complexDiv(z,z),ref=naive(z,z);
      if(ours.re!==1||ours.im!==0)throw new Error(`z/z for z=${z.re}+${z.im}i gave ${ours.re}+${ours.im}i, not 1`);
      if(Number.isFinite(ref.re)&&Math.abs(ref.re-1)<1e-9)throw new Error('the naive reference coped; this case no longer proves anything');
    }
    /* Reference 4: plain Smith, written here, on the case Smith alone still loses. (1e308+1e308i)
       divided by (1+i) is exactly 1e308, but Smith forms (ar + ai*r) = 2e308 first, which overflows.
       The power-of-two prescale is what keeps this finite, so it is checked rather than assumed. */
    const smith=(ar,ai,br,bi)=>{if(Math.abs(br)>=Math.abs(bi)){const r=bi/br,d=br+bi*r;return {re:(ar+ai*r)/d,im:(ai-ar*r)/d};}const r=br/bi,d=br*r+bi;return {re:(ar*r+ai)/d,im:(ai*r-ar)/d};};
    const hard=complexDiv({re:1e308,im:1e308},{re:1,im:1}),plain=smith(1e308,1e308,1,1);
    if(hard.re!==1e308||hard.im!==0)throw new Error(`(1e308+1e308i)/(1+i) gave ${hard.re}+${hard.im}i, expected 1e308`);
    if(Number.isFinite(plain.re))throw new Error('plain Smith coped with the prescale case; it no longer proves the prescale is needed');
    /* Reference 3: the algebraic identity (a*b)/b = a, over eight decades of scale in each part. */
    let worst=0;
    for(let k=0;k<500;k++){
      const a={re:Math.sin(k+1)*Math.pow(10,(k%17)-8),im:Math.cos(2*k+1)*Math.pow(10,(k%13)-6)};
      const b={re:Math.cos(k*0.37)*Math.pow(10,(k%11)-5),im:Math.sin(k*1.7)*Math.pow(10,(k%7)-3)};
      const r=complexDiv(complexMul(a,b),b);
      worst=Math.max(worst,complexAbs(complexSub(r,a))/Math.max(1e-300,complexAbs(a)));
    }
    if(!(worst<1e-14))throw new Error(`(a*b)/b lost ${worst.toExponential(2)} relative accuracy`);
    if(complexAbs({re:3,im:4})!==5)throw new Error('complexAbs failed');
    const p=complexFromPolar(2,Math.PI/3);
    if(Math.abs(complexArg(p)-Math.PI/3)>1e-15||Math.abs(complexAbs(p)-2)>1e-15)throw new Error('polar round trip failed');
    const c=complexConj({re:1,im:-2});
    if(c.re!==1||c.im!==2)throw new Error('complexConj failed');
    const sum=complexAdd({re:1,im:2},3),dif=complexSub({re:1,im:2},{re:0.5,im:-1}),pr=complexMul({re:0,im:1},{re:0,im:1});
    if(sum.re!==4||sum.im!==2)throw new Error('complexAdd with a real operand failed');
    if(dif.re!==0.5||dif.im!==3)throw new Error('complexSub failed');
    if(pr.re!==-1||pr.im!==0)throw new Error('i*i should be -1');
    const rec=complexReciprocal({re:0,im:2});
    if(Math.abs(rec.re)>1e-18||Math.abs(rec.im+0.5)>1e-18)throw new Error('1/(2i) should be -0.5i');
  });

  await test('the Hermitian and bilinear complex products are different and each matches its definition',()=>{
    /* Both are recomputed here from their definitions, by hand, on {re,im} scalars. */
    const n=9,a=allocateComplexField(n),b=allocateComplexField(n);
    for(let i=0;i<n;i++){a.re[i]=Math.sin(i+1);a.im[i]=Math.cos(2*i+1);b.re[i]=Math.cos(i*0.5);b.im[i]=Math.sin(i*1.3);}
    let hr=0,hi=0,ur=0,ui=0;
    for(let i=0;i<n;i++){
      hr+=a.re[i]*b.re[i]+a.im[i]*b.im[i]; hi+=a.re[i]*b.im[i]-a.im[i]*b.re[i];   // conj(a)*b
      ur+=a.re[i]*b.re[i]-a.im[i]*b.im[i]; ui+=a.re[i]*b.im[i]+a.im[i]*b.re[i];   // a*b
    }
    const H=complexFieldDotH(a,b),U=complexFieldDotU(a,b);
    if(Math.abs(H.re-hr)>1e-15||Math.abs(H.im-hi)>1e-15)throw new Error(`DotH ${H.re}+${H.im}i != definition ${hr}+${hi}i`);
    if(Math.abs(U.re-ur)>1e-15||Math.abs(U.im-ui)>1e-15)throw new Error(`DotU ${U.re}+${U.im}i != definition ${ur}+${ui}i`);
    /* If these ever coincide the test has stopped testing the thing it is named for. */
    if(complexAbs(complexSub(H,U))<1e-3)throw new Error('the two products returned the same value on complex data');
    /* DotH(a,a) is real and is the squared norm; DotU(a,a) generally is not. */
    const HH=complexFieldDotH(a,a);
    if(HH.im!==0)throw new Error(`DotH(a,a) must be exactly real, imaginary part was ${HH.im}`);
    if(Math.abs(HH.re-Math.pow(complexFieldNorm2(a),2))>1e-13)throw new Error('DotH(a,a) disagrees with norm2^2');
    if(complexFieldDotU(a,a).im===0)throw new Error('DotU(a,a) happened to be real; pick data where it is not');
    /* Conjugate symmetry: DotH(a,b) = conj(DotH(b,a)). */
    const R=complexFieldDotH(b,a);
    if(Math.hypot(H.re-R.re,H.im+R.im)>1e-15)throw new Error('DotH is not conjugate-symmetric');
    /* The masked/ranged forms agree with a hand-summed subrange. */
    const part=complexFieldDotU(a,b,{start:2,end:5});
    let pr=0,pi=0;for(let i=2;i<5;i++){pr+=a.re[i]*b.re[i]-a.im[i]*b.im[i];pi+=a.re[i]*b.im[i]+a.im[i]*b.re[i];}
    if(Math.abs(part.re-pr)>1e-15||Math.abs(part.im-pi)>1e-15)throw new Error('the ranged DotU disagrees with the hand sum');
    if(Math.abs(complexFieldMaxAbs(a)-Math.max(...Array.from({length:n},(_,i)=>Math.hypot(a.re[i],a.im[i]))))>1e-15)throw new Error('complexFieldMaxAbs failed');
  });

