    complexFieldAXPY(y,alpha,x,axpy); complexFieldCombine(comb,alpha,x,beta,y); complexFieldScale(x,alpha,sc); complexFieldConjugate(x,cj);
    const mag=complexFieldAbs(x),ph=complexFieldArg(x);
